  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Sarah accepts the dinner alone, reasoning that a free meal will not influence her future prescribing decisions.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because GMC guidance on probity is explicit that doctors should avoid hospitality from companies whose products they may prescribe, even where the doctor believes they are personally unaffected. Evidence consistently shows that even modest hospitality influences prescribing. However, the consequences of attending a single dinner are limited and reversible, which keeps it short of a very inappropriate response.', 0),
    (v_s01, 2, 'Sarah accepts the invitation including the dinner and brings her partner along, treating the event as a social occasion.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because accepting hospitality from a pharmaceutical company whose drugs the department prescribes is already a clear conflict of interest, and bringing a partner extends the personal benefit while reframing the event as social to disguise its commercial purpose. This breaches GMC standards on integrity and undermines public trust in the profession.', 1),
    (v_s01, 2, 'Sarah declines the invitation, explains her concern about conflicts of interest, and suggests the company arrange an in-house educational session open to all staff instead.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it directly addresses the GMC''s expectation that doctors avoid conflicts of interest in prescribing decisions, while still leaving open a route for genuine educational engagement that does not involve hospitality. Suggesting an in-house session protects independence and benefits the wider team, fully aligning with professional duty.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'The patient''s right to retain a record of their own consultation, weighed against the GP''s right to know they are being recorded.', 'Very important', 'This is very important because it is the central ethical tension in the situation. GMC guidance recognises that patients may record their own care, but transparency between clinician and patient is a core element of the therapeutic relationship. Daniyaal''s response must be grounded in this balance rather than in his personal discomfort.', 0),
    (v_s02, 1, 'That Daniyaal would find it socially awkward to interrupt the GP in the middle of explaining a serious diagnosis.', 'Not important at all', 'This is not important at all because personal awkwardness is a self-interest concern that should never determine a professional decision. The GMC is clear that doctors and students should act on professional obligations regardless of social discomfort, particularly where transparency and trust are at stake.', 1),
    (v_s02, 1, 'Whether the audio recording is likely to be of high enough quality to be useful to the patient afterwards.', 'Of minor importance', 'This is of minor importance because the technical quality of the recording does not change the underlying issue of whether it should have been disclosed. It is a peripheral practical detail that has minimal bearing on the professional response Daniyaal should choose.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Marcus contacts the medical school welfare office about Aleena, without first speaking to her directly.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because contacting the welfare office without first speaking to Aleena bypasses the most proportionate step — a private direct conversation — and goes behind her back to a formal university body for what is fundamentally a personal welfare matter. The intent is constructive and welfare services do exist to support students, so the action is not harmful in itself. However, GMC and UCAT principles consistently favour local resolution before formal channels, especially where a peer''s autonomy and dignity could be preserved through a direct approach first.', 0),
    (v_s03, 2, 'Marcus speaks to Aleena privately and gently shares his concerns about taking medication that has not been formally prescribed for her, encouraging her to register with a GP.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it is a private, respectful, and direct conversation that addresses both Aleena''s wellbeing and the professional issue of taking medication without a formal prescription. It models the GMC principles of supporting colleagues and acting with honesty, while preserving Aleena''s dignity.', 1),
    (v_s03, 2, 'Marcus reports Aleena directly to the dean of the medical school for unprofessional conduct.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it is a grossly disproportionate first response that bypasses every more measured option available. It risks serious damage to Aleena''s standing without any attempt to understand the situation or offer support, breaching the GMC expectation that students act with judgement and care toward colleagues.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 1, 'That Mr Henderson appears emotionally invested in giving the gift and might feel hurt if Olamide refuses it outright.', 'Important', 'This is important because the way Olamide responds will affect Mr Henderson''s emotional state and the dignity of his closing interaction with her care team. GMC guidance requires that doctors handle these situations sensitively — not that they accept gifts they should not, but that any refusal is delivered with care.', 0),
    (v_s04, 1, 'Whether the envelope contains cash, which is treated very differently under hospital and GMC guidance from a card or small token.', 'Very important', 'This is very important because the GMC and most NHS trusts draw a clear distinction between modest tokens of thanks and gifts of money. Cash gifts can damage public trust, create perceptions of preferential treatment, and pose probity risks. The form of the gift directly determines what response is professionally appropriate.', 1),
    (v_s04, 1, 'That several of Olamide''s colleagues on the ward have accepted similar gifts from grateful patients in the past without consequence.', 'Not important at all', 'This is not important at all because the behaviour of others does not justify departing from professional standards. The GMC requires every doctor to apply the principles of probity individually; common practice on a ward is irrelevant to whether a particular gift should be accepted.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 2, 'Theo angrily tells the consultant to ''shut up and act professionally'' in front of the entire theatre team during the procedure.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because public, aggressive confrontation in the operating theatre risks the patient''s safety mid-procedure, humiliates the consultant, and damages team functioning. The underlying concern is valid, but the GMC framework prioritises raising concerns through proportionate, respectful means — not confrontational outbursts in clinical settings.', 0),
    (v_s05, 2, 'Theo focuses on the surgical technique throughout the procedure and decides not to raise the issue at all afterwards, hoping it will not happen again.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because failing to raise a concern about disrespectful conduct lets the behaviour go unchallenged, but the immediate harm in this instance is limited as the patient remains unaware. The right response is still to address it; pure inaction is the wrong choice but does not produce serious lasting damage in this single instance.', 1),
    (v_s05, 2, 'Theo says nothing during the operation but later submits anonymous feedback through his medical school''s placement evaluation form.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because the action does raise the concern through a legitimate route, but anonymous feedback delivered weeks later is far less direct and less likely to change behaviour than a private, timely conversation with the consultant. It addresses the issue without confronting it head-on.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Naomi tries one more direct approach — phoning Toby and visiting his accommodation — to find out whether something has happened to him.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it shows genuine concern for Toby as a person while still addressing the project''s needs. Sustained silence after multiple messages may indicate that something is wrong; checking in directly aligns with the professional duty to support colleagues and to treat people with kindness.', 0),
    (v_s06, 2, 'Naomi raises the issue with the module leader straight away to ask for an extension on the group''s behalf.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because escalating to the module leader is a reasonable formal step, but it is premature when Naomi has not yet tried alternative means of contacting Toby directly. Going to staff before exhausting peer-level options misses the chance for a quicker, more personal resolution.', 1),
    (v_s06, 2, 'Naomi posts a message in the group chat publicly criticising Toby for letting everyone down and demanding he respond immediately.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because public criticism in the group chat shames Toby in front of all his peers and demands an immediate response from someone whose prolonged silence after two unanswered messages may itself signal personal difficulty or mental distress. Adding humiliation and pressure to someone potentially struggling could significantly worsen the situation, damage group trust, and drive Toby further into withdrawal. The GMC framework prioritises kindness, colleague welfare, and proportionate raising of concerns — this action fails all three.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That Aiyana''s rotation in this particular clinic is only a few weeks long.', 'Of minor importance', 'This is of minor importance because the duration of the rotation does not change the underlying ethical position. GMC guidance on conscientious objection applies regardless of how long someone is assigned to a clinical area. The brevity of the placement is a peripheral factor.', 0),
    (v_s07, 1, 'The GMC''s guidance permitting conscientious objection while requiring patients to be referred promptly to a colleague who can provide care without delay.', 'Very important', 'This is very important because the GMC framework is the controlling professional standard. It establishes that conscientious objection is permitted but that doctors must not obstruct or delay patient care, and must refer patients on. Following this guidance is the foundation of any appropriate response Aiyana can make.', 1),
    (v_s07, 1, 'Whether Aiyana''s supervisor will think less of her or it could affect her career references later.', 'Not important at all', 'This is not important at all because professional decisions cannot be driven by self-interest or fear of personal consequences. The GMC explicitly protects doctors'' right to raise conscientious objections appropriately, and concerns about career impact must not deter Aiyana from acting in line with her conscience and the rules that govern it.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Joon-ho ignores the discrepancy, reasoning that monitoring his classmate''s logbook is not his job.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because falsified clinical records are a serious form of professional dishonesty with safeguarding implications for future patients of an under-qualified clinician. The GMC and the GDC both require students to act on information about misconduct rather than turn away. Inaction here is a form of complicity.', 0),
    (v_s08, 2, 'Joon-ho speaks to Faisal privately and tells him that the falsified entries must be withdrawn before submission.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it confronts the integrity issue directly, gives Faisal the chance to correct the record himself, and aligns with professional duties around honesty. It avoids unnecessary escalation while making clear that fabricated entries cannot stand.', 1),
    (v_s08, 2, 'Joon-ho reports the falsified entries to the dental school''s professionalism lead without speaking to Faisal first.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because the issue is genuinely serious enough to warrant escalation, and reporting fabrication is the right ultimate destination — but skipping a direct conversation removes Faisal''s chance to retract the entries voluntarily. A staged response (speak to Faisal first, escalate if not addressed) would be more proportionate.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 1, 'That the supervisor is the chair of the department and may influence the student''s future references and career.', 'Not important at all', 'This is not important at all because hierarchical pressure or potential career consequences must not determine whether a researcher participates in selective data exclusion. The GMC and research integrity frameworks are unequivocal: research misconduct cannot be excused by the seniority of the person requesting it.', 0),
    (v_s09, 1, 'The journal''s stated guidelines on the handling and disclosure of outlier exclusion.', 'Important', 'This is important because journal policies set out the formal expectations for how data must be reported and exclusions justified. Following them is part of acting transparently, but the deeper issue — whether removal of these specific points is methodologically valid — sits above any individual journal''s specific rules.', 1),
    (v_s09, 1, 'Whether the supervisor has provided a documented, methodologically valid reason for excluding each individual data point.', 'Very important', 'This is very important because the legitimacy of the exclusions is the central question. Removing data with valid methodological justification is acceptable; removing data simply because their inclusion produces unwanted results is research misconduct. Without documentation and rationale, the student cannot proceed in good conscience.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'Idris does nothing, reasoning that he and Ben are not close enough for personal conversations.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because failing to check in on a clearly struggling flatmate misses an important opportunity to support him, but the harm is one of omission rather than a direct worsening of the situation. A reasonable next step is still available to Idris if he chooses to take it.', 0),
    (v_s10, 2, 'Idris contacts Ben''s family directly, using a phone number he finds on Ben''s social media profile.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it bypasses Ben''s autonomy entirely, breaches his privacy by sourcing contact details without consent, and could seriously damage trust if he learns of it. There is no immediate safety emergency that would justify this; the proportionate first step is to speak to Ben himself.', 1),
    (v_s10, 2, 'Idris knocks on Ben''s door and gently asks how he is doing, offering to listen if he wants to talk.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it is direct, respectful, and proportionate to the level of concern. It opens the door to support without forcing a conversation, respects Ben''s autonomy, and puts Idris in a position to escalate appropriately if he learns Ben is in real distress.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Tobi mentions the issue informally to a few colleagues during the shift and asks the ward sister again about the timeline for the replacement.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Tobi is raising the concern locally, which is constructive, but speaking informally to colleagues and chasing the ward sister does not match the seriousness of an in-use device producing erratic readings. GMC Good Medical Practice requires doctors to act promptly to protect patient safety, which here means a formal incident report and a clear warning that the machine is unreliable. Tobi has taken a step but stopped short of the appropriate professional action.', 0),
    (v_s01, 2, 'Tobi adds a clearly visible warning sign on the machine and reports the fault formally through the trust''s clinical incident reporting system that day.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Tobi is acting promptly to protect patients from a known equipment fault and using the proper formal channel. GMC Good Medical Practice requires doctors to take prompt action where they have good reason to believe that patient safety is being compromised. The visible warning prevents immediate harm while the formal report ensures the issue is investigated and resolved at organisational level.', 1),
    (v_s01, 2, 'Tobi assumes the ward sister has the situation under control and continues to use the machine without further action.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because patient safety is the doctor''s personal responsibility regardless of what others may be doing. Assuming someone else has it under control while a faulty machine remains in clinical use is the inaction trap. GMC Good Medical Practice is clear that doctors must take prompt action when patients are at risk; deferring to others or to an administrative process does not discharge that duty.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'That the GP appears frustrated and Aisha is reluctant to ask any clarifying questions for fear of slowing down the appointment.', 'Not important at all', 'This is not important at all because professional learning and the patient''s care should never be subordinated to a colleague''s mood or to keeping the appointment running on time. GMC Good Medical Practice expects medical students to engage constructively with patients and their education. Personal discomfort about how a senior might react is the self-interest trap and has no bearing on what considerations matter for the clinical decision.', 0),
    (v_s02, 1, 'The patient''s subjective experience of feeling much better since switching to the herbal supplement.', 'Important', 'This is important because the patient''s lived experience and the reasons he changed his treatment shape the conversation that needs to happen and help the team understand what matters to him. It is not very important on its own, because symptom relief from a herbal supplement does not by itself prove the treatment is safe or that diabetes control is adequate, but it is genuinely relevant to building rapport, exploring his beliefs, and giving him useful information. GMC Good Medical Practice emphasises listening to patients and treating them as partners in their care.', 1),
    (v_s02, 1, 'Whether the patient has been given clear information about the medical risks of stopping his prescribed metformin.', 'Very important', 'This is very important because informed decision-making sits at the heart of patient autonomy. GMC Good Medical Practice requires doctors to give patients the information they need to make decisions, including the consequences of not taking prescribed treatment. If the patient has not been clearly informed about the risks of stopping metformin, his choice is not truly informed and the team has not yet fulfilled its professional duty.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Hayden ignores the comment to keep the working relationship pleasant and writes it off as a one-off.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because failing to challenge racist conduct toward a patient violates GMC Good Medical Practice duties around treating patients with respect and not discriminating against them. Letting it pass also condones the behaviour and means it is more likely to be repeated. The desire to keep a relationship pleasant is the self-interest trap; professional duty does not yield to social comfort.', 0),
    (v_s03, 2, 'Hayden tells Marcus quietly but firmly that the comment was racist and unacceptable, and he expects Marcus to apologise and not repeat it.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Hayden is addressing the issue directly, privately, and without humiliating Marcus, while making clear that the behaviour breaches professional standards. GMC Good Medical Practice requires doctors and students to challenge discrimination and to support a respectful environment for patients and colleagues. Direct, calm intervention is the recommended first step before any escalation.', 1),
    (v_s03, 2, 'Hayden waits until the end of the placement and writes a detailed account of the incident in his end-of-placement feedback form.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because formally recording the incident is right and shows Hayden is taking the matter seriously, but waiting until the end of the placement misses the opportunity to challenge the behaviour at the time and allows it to go unaddressed for weeks. GMC Good Medical Practice expects timely action on professionalism concerns. Recording the incident is correct; delaying it is not.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Dr Ndiaye writes the prescription but adds a note in the patient''s file stating that she did so under the direction of the consultant.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because Dr Ndiaye has still acted beyond her competence — adding a documentation note does not transfer responsibility for the prescribing decision back to the consultant. GMC Good Medical Practice is unambiguous that doctors must recognise the limits of their competence. The consequences here may be limited if the consultant does countersign and the prescription happens to be correct, but the underlying action remains professionally wrong.', 0),
    (v_s04, 2, 'Dr Ndiaye tells the consultant that she is not competent to prescribe chemotherapy and asks whether the registrar can be reached briefly between cases or another senior can prescribe.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Dr Ndiaye is recognising the limits of her competence, refusing to act unsafely, and constructively offering a workable alternative. GMC Good Medical Practice requires doctors to recognise and work within the limits of their competence and to ask for help when needed. Asking for help is professionalism, not weakness, and the seniority of the request does not override the duty to prescribe safely.', 1),
    (v_s04, 2, 'Dr Ndiaye writes the prescription as requested because the consultant is more senior and has agreed to countersign it later.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because prescribing chemotherapy without the relevant competence puts the patient at serious risk of harm, and seniority does not authorise unsafe practice. GMC Good Medical Practice makes clear that doctors must not act beyond their competence even when asked to by a senior. A countersignature after the fact does not retroactively make an unsafe prescription safe.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 1, 'That the son''s anger may stem from grief, fear, or shock about his mother''s deterioration rather than a personal attack on the team.', 'Important', 'This is important because understanding why the son is reacting this way directly shapes how Dr Lin should respond — empathy and a private space to talk are likely to de-escalate distress more effectively than a defensive reaction. GMC Good Medical Practice expects doctors to communicate sensitively with patients and families, especially in difficult circumstances. It is not very important in the same sense as the safety of those present, but it is genuinely relevant to the choice of response.', 0),
    (v_s05, 1, 'The safety of staff, other patients, and visitors in the corridor.', 'Very important', 'This is very important because patient and staff safety is the highest priority in any escalating situation. GMC Good Medical Practice requires doctors to act to protect patients, and the trust has a duty of care to its staff and other visitors. Dr Lin must decide whether to move the conversation to a private room, ask for support, or call for security based on this assessment — ignoring it would be negligent.', 1),
    (v_s05, 1, 'That Dr Lin feels personally embarrassed by being shouted at in front of senior colleagues.', 'Not important at all', 'This is not important at all because personal embarrassment is the self-interest trap and should never drive a clinical or professional decision. GMC Good Medical Practice expects doctors to act in patients'' and others'' best interests regardless of how a situation makes them feel. How Dr Lin appears to colleagues is irrelevant; what matters is the welfare of the patient, the family, and others present.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Tomás explains the data protection breach to the other student, asks them to delete the photograph in front of him, and reports the incident to the placement supervisor that day.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Tomás is addressing the immediate confidentiality breach by ensuring the data is deleted, and meeting the professional duty to escalate by reporting it. GMC Good Medical Practice and information governance rules require that breaches of patient confidentiality be reported, regardless of the intentions of the person involved. Both steps — direct correction and formal reporting — are necessary.', 0),
    (v_s06, 2, 'Tomás privately advises the other student to be more careful with patient information in future but does not pursue the issue further.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because Tomás has at least raised the concern with the student, but he has failed to ensure the photo is deleted and has not reported a clear confidentiality breach. GMC Good Medical Practice requires that breaches of patient confidentiality be addressed and reported. The consequences may be limited if the photo is never shared, but the response leaves a real risk that the data persists and that no learning occurs beyond a vague warning.', 1),
    (v_s06, 2, 'Tomás says nothing because the other student claimed the photo was anonymised and they meant well.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the photo is not actually anonymised — it contains the patient''s full name and date of birth — and good intentions do not justify a confidentiality breach. GMC Good Medical Practice and data protection law are clear that patient information must be protected. Inaction on a confidentiality breach is the inaction trap and exposes the patient and the trust to real harm.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That Mrs Whitaker has explicitly told Aanya she ''walked into a door'' and may not appreciate further questioning.', 'Of minor importance', 'This is of minor importance because while Mrs Whitaker''s stated explanation is part of the picture, the pattern of bruising, the nervous laughter, and the partner''s behaviour together raise a credible safeguarding concern that cannot be set aside on the patient''s word alone. Professional safeguarding guidance recognises that adults experiencing domestic abuse may not initially disclose. Her explanation deserves consideration but does not displace the safeguarding duty.', 0),
    (v_s07, 1, 'The possibility that Mrs Whitaker is experiencing domestic abuse and may be at risk of further harm.', 'Very important', 'This is very important because adult safeguarding is a core professional duty for all healthcare practitioners, including dental students under supervision. GDC Standards for the Dental Team (Principle 8: raise concerns if patients are at risk) requires practitioners to act to protect anyone at risk of serious harm. Recognising the possibility of abuse is the first step to ensuring Mrs Whitaker has a safe opportunity to disclose and access support.', 1),
    (v_s07, 1, 'That raising a safeguarding concern could damage the practice''s relationship with a long-standing patient.', 'Not important at all', 'This is not important at all because a patient''s safety is never subordinate to the convenience or commercial interests of a practice. GDC Principle 8 and safeguarding obligations apply regardless of how long someone has been a patient or how it might affect future appointments. This is the self-interest trap dressed up as practice loyalty.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Dr Aroha makes a sarcastic remark about Dr Patel''s punctuality at the next handover, in front of the team, hoping it will shame him into changing his behaviour.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because public humiliation breaches professional standards of respect for colleagues and would damage team trust. GMC Good Medical Practice requires doctors to communicate respectfully with colleagues. Sarcasm in front of the team is the confrontation trap — it does not constructively address the underlying issue and could make handover dynamics worse for everyone, including patients.', 0),
    (v_s08, 2, 'Dr Aroha speaks to Dr Patel privately to explain how the lateness is affecting handover quality and asks whether something is making it difficult to arrive on time.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Dr Aroha is addressing the issue directly, privately, and constructively, while leaving room for Dr Patel to explain any underlying difficulty. GMC Good Medical Practice expects doctors to raise concerns about colleagues'' conduct in a way that supports both patient safety and the colleague. Direct, private conversation is the preferred first step before any formal escalation.', 1),
    (v_s08, 2, 'Dr Aroha begins arriving at handover early herself and quietly takes notes from the night team to fill in any gaps later, hoping the situation will improve on its own.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because while Dr Aroha is mitigating the immediate gaps in handover, she is masking a problem that is putting patients at risk and avoiding the conversation that is needed. GMC Good Medical Practice requires doctors to raise concerns about practice that affects patient safety. The consequences are limited because patients are partly protected, but the underlying issue persists and the inaction trap applies.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 2, 'Yusuf approaches Dr Crawford directly and asks whether the relationship is true.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because while Yusuf is taking the concern seriously rather than ignoring it, directly confronting a senior clinician about a suspected serious boundary breach — based on second-hand information — risks compromising any subsequent investigation and exposes Yusuf to real difficulty given the power imbalance. GMC Good Medical Practice and medical school professionalism guidance direct that concerns of this kind go through the professionalism lead, who has the authority and information to investigate properly. The consequences here are limited because Yusuf is at least raising the issue, but the route is wrong.', 0),
    (v_s09, 2, 'Yusuf raises the matter with the medical school''s professionalism lead, naming the source of the information so that it can be looked into appropriately.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because a sexual or romantic relationship with a current patient is a serious breach of professional boundaries that GMC Good Medical Practice explicitly prohibits, and it requires investigation by people with the authority and information to act. Naming the source allows the issue to be looked into properly. Loyalty to a fellow student does not override the duty to raise concerns.', 1),
    (v_s09, 2, 'Yusuf agrees to keep the information to himself because his fellow student asked him to and he doesn''t want to seem disloyal.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because keeping silent about a serious breach of professional boundaries could allow harm to a patient who may be in a vulnerable position relative to her consultant. GMC Good Medical Practice is unambiguous that doctors and students must not let personal loyalty interfere with the duty to raise concerns. This is the self-interest trap masquerading as friendship loyalty.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 1, 'That speaking to a journalist about staff conversations could breach patient confidentiality and the trust of colleagues.', 'Very important', 'This is very important because confidentiality is a foundational professional duty under GMC Good Medical Practice, and breaches harm both individual patients and the wider relationship between healthcare staff and the public. Even off-the-record conversations with journalists can leak details that identify patients or colleagues. Eshe is professionally bound to protect that information.', 0),
    (v_s10, 1, 'That the public has a legitimate interest in transparency about serious incidents at hospitals.', 'Of minor importance', 'This is of minor importance because while public transparency about serious incidents is a real and valuable principle, it is not Eshe''s role to deliver it through an informal off-the-record briefing. Trusts have formal processes — incident investigations, regulator reporting, and official press communications — that exist precisely to handle this. The principle exists but does not bear meaningfully on Eshe''s individual decision.', 1),
    (v_s10, 1, 'That the journalist has promised the conversation would be ''off the record''.', 'Not important at all', 'This is not important at all because ''off the record'' offers no enforceable protection for confidential information and does not displace any professional duty. GMC Good Medical Practice requires confidentiality regardless of who is asking or what assurances they give. Relying on a journalist''s informal promise is the self-interest trap of seeking permission to do something that professional standards already prohibit.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Akin tells the patient that he understands her wishes and agrees to keep what she has said between the two of them.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because domestic abuse poses a serious risk of harm and the GMC is clear that confidentiality is not absolute when there is risk of significant harm. Promising secrecy in this situation also misleads the patient, prevents her from accessing safeguarding support, and breaches Akin''s professional duty as a healthcare student to act on safety concerns. A medical student should never agree to conceal disclosures of violence from the supervising clinician.', 0),
    (v_s01, 2, 'Akin gently explains that he cannot keep this conversation entirely confidential because of his duty to keep her safe, and reassures her that the GP and support services can help.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it reflects the GMC''s guidance on confidentiality and safeguarding: information must be shared when there is a risk of serious harm. Akin is being honest with the patient about the limits of confidentiality, treating her with dignity, and signposting to appropriate support, all while acting within his role as a student observer.', 1),
    (v_s01, 2, 'Akin says nothing in the moment but plans to mention it to the GP at the end of the day in their debrief.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because while Akin does intend to share the disclosure, his silence in the moment leaves the patient with the false impression that her information will be kept private. Honesty with patients is a core GMC principle, and the delay also risks the patient leaving without being offered safeguarding support. It is not catastrophic because the information will be shared the same day, but the lack of transparency at the time of disclosure is a meaningful professional failing.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'Whether other Jehovah''s Witnesses might make different decisions in similar situations.', 'Of minor importance', 'This is of minor importance because the decision in question belongs to this individual patient, and what other people of the same faith might choose has only marginal bearing on her care plan. While it can occasionally inform background understanding, it does not change the team''s duty to respect her stated, informed wishes. It is not entirely irrelevant, but it should not influence the actual decision-making.', 0),
    (v_s02, 1, 'That Hannah personally feels the patient is making the wrong decision.', 'Not important at all', 'This is not important at all because a competent adult patient has the legal and ethical right to refuse treatment, even where the consequences are serious, and the GMC requires clinicians to respect autonomy. Hannah''s personal disagreement with the decision is irrelevant to the team''s duty of care and would be an inappropriate basis for influencing the consultation.', 1),
    (v_s02, 1, 'Whether the patient has been given full information about the risks of refusing transfusion and has the capacity to make this decision.', 'Very important', 'This is very important because a refusal of treatment is only valid if it is informed and made by a patient with capacity. The GMC and the principle of autonomy require that patients understand the consequences of their choices. Confirming both adequate information and capacity is essential to ensuring the team is genuinely respecting an informed decision rather than inadvertently allowing harm through inadequate consent.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Dr Marek joins in with one comment to keep things light, and then changes the subject to something less offensive.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because participating in degrading speech about a patient is itself a breach of dignity and the GMC''s principle of treating patients with respect. Adding to the mockery normalises this behaviour among colleagues and undermines the professional culture of the team. A diversion afterwards does not undo the harm caused by participating, even briefly.', 0),
    (v_s03, 2, 'Dr Marek waits until the conversation ends, then privately speaks to his colleagues about why their comments were inappropriate and how it could affect patient care.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it directly addresses the issue with the people involved, in a private and respectful way, in line with the GMC''s expectations around dignity and challenging unprofessional behaviour. It avoids public confrontation while still acting on a clear professional concern, and it gives colleagues the chance to reflect and change their conduct.', 1),
    (v_s03, 2, 'Dr Marek says nothing at the time but raises the issue anonymously as a hypothetical example during the next consultant-led teaching session.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because it sidesteps the direct private conversation that the GMC expects when raising concerns about a colleague''s behaviour, and instead repurposes a consultant-led teaching session for an indirect callout. The colleagues are unlikely to recognise themselves in an anonymous hypothetical, so the actual unprofessional conduct goes unaddressed, and using teaching time for what should be a personal conversation is itself a misuse of the session. It is not awful because the broader reflection has some educational value and the underlying intent is constructive, but a direct private conversation was clearly available and would have been the appropriate response.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 1, 'Whether the discrepancy might be explained by a simple administrative error from the previous shift.', 'Of minor importance', 'This is of minor importance because, while a paperwork error is a possible explanation, it does not change the fundamental duty to escalate and document the discrepancy through formal controlled drugs governance channels. The GMC and controlled drugs regulations require that any unaccounted-for stock is treated seriously and investigated through proper processes regardless of the suspected cause. The possibility of a simple error is useful background that may emerge during investigation, but it should not influence whether or how Dr Lin acts in the moment.', 0),
    (v_s04, 1, 'That Dr Lin is tired at the end of a night shift and may not want to take on extra paperwork.', 'Not important at all', 'This is not important at all because personal fatigue and convenience must never determine whether professional duties around patient safety and controlled drugs are followed through. The GMC is clear that doctors have a duty to act on concerns, and missing controlled drugs is exactly the kind of issue that requires immediate proper reporting regardless of the inconvenience involved.', 1),
    (v_s04, 1, 'The possibility that controlled drugs are being misused or diverted by a member of staff.', 'Very important', 'This is very important because controlled drug diversion is a patient safety issue, a regulatory issue, and potentially a criminal one. The GMC and controlled drugs legislation place strong obligations on healthcare staff to investigate and report unaccounted-for stock. Failing to take this possibility seriously would put patients at risk and could allow harm to a struggling colleague to continue undetected.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 2, 'Maya does not reply to the note and chooses not to mention it to anyone, planning simply to behave professionally at the next appointment.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because the decision not to reply is correct, but failing to inform a supervisor leaves Maya handling a boundary issue without support and means there is no record if the situation escalates or becomes uncomfortable. The GDC and equivalent professional standards expect transparency about boundary concerns. The consequences are limited because no breach of conduct has yet occurred, but it falls short of full professional practice.', 0),
    (v_s05, 2, 'Maya keeps the note and decides she will text the patient once his current course of treatment ends, viewing this as a way to maintain professional boundaries until then.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because professional standards strongly discourage pursuing personal or romantic relationships with patients, including those very recently under one''s care, due to the inherent power imbalance in clinical relationships. Planning to act on the patient''s interest, even after a delay, fundamentally compromises Maya''s professional integrity and exposes both parties to harm.', 1),
    (v_s05, 2, 'Maya disposes of the note and informs her supervising dentist about what happened, asking for advice on how to handle the next appointment.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it addresses the boundary issue transparently, seeks senior input as is expected of a student, and ensures there is a record of the incident in case it recurs. It reflects the GDC and GMC principles of probity, professional boundaries, and appropriate use of supervision, and it protects both Maya and the patient from any ambiguity about the professional relationship.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Dr Tomas politely refuses, explains that GMC guidance discourages prescribing for family members, and offers to help her arrange a GP appointment.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it reflects explicit GMC guidance that doctors should avoid prescribing for themselves or those close to them, except in emergencies. Dr Tomas maintains professional standards while still supporting his mother by helping her access proper care. He addresses the underlying issue (her insomnia) through appropriate channels rather than dismissing her concerns.', 0),
    (v_s06, 2, 'Dr Tomas writes a small private prescription for a few nights'' supply, treating it as a temporary bridge until she can see her GP.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it directly contravenes GMC guidance on prescribing for family members. There has been no clinical assessment, his objectivity is compromised by the family relationship, zopiclone has dependence and abuse potential, and his mother''s insomnia could mask an underlying physical or mental health issue that goes undiagnosed. The size of the prescription does not change the principles at stake.', 1),
    (v_s06, 2, 'Dr Tomas tells his mother she should see her GP first, but says he might consider prescribing if she still cannot get an appointment after a few weeks.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because the immediate response (signposting to her GP) is correct, but leaving the door open to prescribing later compromises Dr Tomas''s professional position and contradicts GMC guidance regardless of access difficulties. It is not catastrophic because no prescription has yet been written, but it sets up a problematic future arrangement that should not be on the table at all.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That arranging a professional interpreter would slow the GP''s already busy clinic.', 'Not important at all', 'This is not important at all because clinical convenience and time pressures must never override safeguarding considerations or quality of care. The GMC is explicit that clinicians should use trained interpreters where possible and should not rely on family members, particularly children, for sensitive consultations. Allowing workload to drive this decision would put the child and the standard of the patient''s care at risk.', 0),
    (v_s07, 1, 'That the family appear comfortable using the child as a translator.', 'Of minor importance', 'This is of minor importance because the family''s apparent comfort does not change the underlying safeguarding and clinical concerns. Many families do not recognise the burden placed on a child translating sensitive material, and the GP retains professional responsibility for safeguarding regardless of the family''s preferences. It can be acknowledged respectfully but should not drive the decision.', 1),
    (v_s07, 1, 'Whether using the child as a translator could be psychologically harmful to him or compromise the quality of the consultation.', 'Very important', 'This is very important because it directly engages safeguarding duties, the GMC''s principles on protecting children, and the integrity of the clinical assessment. Children translating sensitive women''s health information can experience significant psychological harm, and using them risks errors in translation that could compromise diagnosis and care. This consideration should drive the decision to arrange a professional interpreter.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Lerato tells Dapo she did notice the pattern, validates his experience, and offers to support him in raising it with the tutor while asking what kind of help he would find most useful.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it acknowledges the discrimination, supports a colleague who has shared a difficult experience, and respects his autonomy by checking what he wants rather than acting unilaterally. It aligns with professional values around dignity and equality and the GMC''s expectation that future doctors challenge discrimination, while keeping Dapo at the centre of how the issue is taken forward.', 0),
    (v_s08, 2, 'Lerato decides not to act, reasoning that she is not directly involved and that Dapo is the one who should raise it if he wants to.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because passively framing discrimination as someone else''s problem fails the professional duty to challenge unfair behaviour and contribute to an inclusive learning environment. It is not awful because Dapo has been listened to and Lerato has not made things worse, but failing to offer any support or to consider any further action is a clear shortcoming against GMC values around dignity and equality.', 1),
    (v_s08, 2, 'Lerato directly confronts Ben after the next tutorial, calmly and privately, and tells him that his behaviour towards Dapo is discriminatory.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because addressing discriminatory behaviour directly is generally a positive professional act, but doing so without first checking with Dapo about how he would like the situation handled risks undermining his agency and could escalate matters in ways he is not prepared for. A better first step is to support Dapo and act with rather than for him; the action is well-intentioned but skips that important step.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 1, 'The link between academic integrity and future clinical and professional integrity.', 'Very important', 'This is very important because honesty and integrity are core GDC and GMC principles, and habits formed during training tend to carry into professional practice. Dishonesty in coursework can foreshadow dishonesty in clinical records, prescriptions, and patient communication, all of which affect patient safety. This consideration goes to the heart of why academic dishonesty in healthcare students is treated so seriously.', 0),
    (v_s09, 1, 'That confronting Carlos may make their living situation awkward for the rest of the year.', 'Not important at all', 'This is not important at all because personal convenience and social comfort should never determine whether someone acts on a serious integrity issue. This is a classic self-interest trap: the GMC and GDC make clear that fear of awkwardness is not an acceptable reason to ignore professional concerns, particularly those that touch on the integrity of healthcare professionals.', 1),
    (v_s09, 1, 'The fact that Carlos''s actions, if discovered, could put his place on the dental course at serious risk.', 'Of minor importance', 'This is of minor importance because the consequences for Carlos should not be the driver of Jonas''s response — the integrity issue must be addressed regardless of what might happen to the person who committed it. Allowing concern for a colleague''s career to weigh heavily here is precisely the kind of consideration that can lead to inaction or to softening a clearly unprofessional act. It is not entirely irrelevant, as it may shape how Jonas raises the issue with Carlos, but it should not influence whether he raises it at all.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'Sienna stays at home but does not contact the consultant directly, instead asking a fellow student to pass on a verbal message that she is unwell.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because the core decision not to attend is correct and protects vulnerable patients, but the communication falls short of professional standards. The GMC and placement protocols expect direct, timely, and clear communication with supervisors when absences occur. A relayed verbal message risks miscommunication and signals less professional accountability than a direct email or call.', 0),
    (v_s10, 2, 'Sienna takes anti-diarrhoeal medication and travels to the placement, planning to manage her symptoms long enough to complete the assessment.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because attending a clinical area with active gastrointestinal symptoms exposes elderly and immunocompromised patients to a serious infection risk, in clear breach of infection control standards and the GMC''s principle that patient safety is paramount. Prioritising a personal assessment over patient welfare is exactly the kind of self-interested decision that ethical guidance is designed to prevent.', 1),
    (v_s10, 2, 'Sienna emails the placement coordinator and the assessing consultant first thing, explains she is unwell with gastrointestinal symptoms and cannot attend, and asks how the assessment can be rearranged.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it puts patient safety first by avoiding contact with vulnerable patients, communicates directly and transparently with the relevant supervisors as the GMC expects, and takes responsibility for arranging an alternative. It models the professional behaviour expected of healthcare students and reflects the priority of patient welfare over personal goals.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 1, 'Whether the current staffing situation could put patients at immediate risk overnight.', 'Very important', 'This is very important because patient safety is the highest priority in GMC Good Medical Practice. If staffing levels create immediate risk to patients overnight, this overrides almost all other considerations and must drive Sam''s decision about whether and how to escalate, and to whom.', 0),
    (v_s01, 1, 'That the rota coordinator has not responded helpfully to the F1''s concerns in previous weeks.', 'Of minor importance', 'This is of minor importance because the past lack of response has some relevance — it tells Sam something about the local culture and may shape who she escalates to next — but it should not determine whether she acts. A pattern of unresponsiveness is more reason to escalate further up, not less, and does not change tonight''s safety duty.', 1),
    (v_s01, 1, 'That formally escalating concerns may make Sam appear to be overreacting or stepping outside her role as a student.', 'Not important at all', 'This is not important at all because how Sam will be perceived should never prevent her from raising a genuine patient safety concern. Worry about looking like she is ''overreacting'' is a self-interest consideration that the GMC explicitly says must not override professional duty, and students are expected to raise concerns through appropriate channels.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 2, 'Tomas asks the partner to step outside and then asks the patient again, in private, whether she is ''completely sure'' she does not want blood, in case she would change her mind without her partner present.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful, because pressing a patient with established capacity to repeat her decision in private — after her partner has been removed — moves towards pressure and undermines respect for autonomy. It is wrong to imply her decision needs further justification, but it stops short of overriding her wishes and does not, by itself, cause significant harm.', 0),
    (v_s02, 2, 'Tomas privately tells the partner that, if the patient becomes unconscious overnight, the medical team can quietly administer blood without her knowing.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it directly proposes a violation of an autonomous patient''s expressed wishes and would amount to assault. The GMC and the law are unambiguous: a patient with capacity has the right to refuse any treatment, including life-saving treatment, and clinicians may not act on the family''s wishes against the patient''s.', 1),
    (v_s02, 2, 'Tomas explores alternative treatments such as iron infusions and tranexamic acid with the senior team and reassures the partner that everything possible within the patient''s wishes will be done.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it respects the patient''s autonomy, fulfils the duty to optimise care within her stated wishes, and supports the family without misleading them. Exploring alternatives that do not involve blood products is exactly the kind of partnership-based, patient-centred care that GMC Good Medical Practice describes.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Eli quietly approaches the F1 a few minutes later to check how she is, acknowledges what happened, and offers to support her if she would like to discuss the incident with the consultant.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it offers private support to a colleague who has been publicly humiliated and respects the F1''s autonomy in deciding what action she wants taken. It addresses the immediate emotional impact, keeps the door open for proportionate escalation, and aligns with the GMC''s expectations around supporting colleagues.', 0),
    (v_s03, 2, 'Eli loudly tells the staff nurse that her behaviour is unacceptable and that he will be reporting her to the ward manager immediately.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it mirrors the staff nurse''s poor behaviour by responding publicly and aggressively, in front of patients. Public confrontation as a first response damages dignity, undermines trust in the team, oversteps Eli''s role as a student, and is disproportionate to a single incident he has only just witnessed.', 1),
    (v_s03, 2, 'Eli decides to say nothing because the staff nurse is more senior and the disagreement is not really his business as a visiting student.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful, because saying nothing fails the duty to support a colleague being mistreated, but the consequences of a single instance of inaction are limited. Eli is junior, the issue is interpersonal rather than a direct patient safety risk, and silence is wrong but not catastrophic in this single context.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Ahmed declines to issue the note in this appointment and tells the patient he should book a longer appointment with his regular GP next week to discuss it further.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal, because Ahmed correctly declines to issue a certificate that is not medically justified, which protects his probity. However, deferring the conversation to the regular GP without explaining his reasoning, or offering useful alternatives, misses the opportunity to address the underlying stress honestly and may simply pass the same problem onto a colleague.', 0),
    (v_s04, 2, 'Ahmed issues the certificate as requested, reasoning that the patient seems genuinely under pressure and refusing might damage their therapeutic relationship.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because issuing a sickness certificate when no clinical sickness is present is dishonest, breaches the GMC''s probity guidance, and undermines public trust in medical certification. The ''therapeutic relationship'' is not a justification for falsifying clinical documentation.', 1),
    (v_s04, 2, 'Ahmed explains honestly that he cannot certify illness that is not present, acknowledges the patient''s stress, and signposts him to occupational health, talking therapies, and self-help resources.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Ahmed is honest about why he cannot certify what is not present, treats the patient with respect by exploring the underlying stress, and signposts genuinely useful resources. This is exactly the partnership-based, honest approach the GMC requires of doctors handling certification.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 1, 'Whether the prize Theo has applied for is highly competitive or relatively routine.', 'Of minor importance', 'This is of minor importance because the competitiveness of the prize affects how consequential the reference is, but it does not change whether Aisha must be honest. The principles of probity and accuracy in any reference apply equally whether the prize is high-stakes or routine, so this is a marginal consideration only.', 0),
    (v_s05, 1, 'The accuracy and honesty of any reference Aisha provides, given that the prize panel will rely on it to make a decision.', 'Very important', 'This is very important because honesty in references is a core probity duty under GMC and GDC guidance. A panel relying on a peer reference must receive an accurate account; providing a knowingly inflated reference would be a form of dishonesty that misleads decision-makers and disadvantages other candidates.', 1),
    (v_s05, 1, 'That Theo has been a kind flatmate to her personally and refusing to write a positive reference might damage their friendship.', 'Not important at all', 'This is not important at all because personal relationships must never override professional probity. The GDC and GMC are explicit that personal loyalty cannot justify dishonesty or inflated assessments of a colleague''s professional behaviour, regardless of how kind the colleague has been outside work.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Yusuf agrees with the consultant and adds his own anecdote about a ''difficult'' family from a similar background that he saw on a previous rotation.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it actively reinforces discriminatory thinking and adds Yusuf''s own voice to negative generalisations about a patient''s family. The GMC explicitly requires doctors to challenge discrimination, not contribute to it, and adding an anecdote further entrenches the original comment as a pattern.', 0),
    (v_s06, 2, 'Yusuf decides he will mention his discomfort to the consultant the following week, after the next clinic, when the comment feels less raw.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal, because Yusuf does eventually plan to address it, which is better than silence. However, raising it a week later and out of context is far less effective than challenging the comment closer to the time, and risks the consultant either not remembering it clearly or feeling ambushed.', 1),
    (v_s06, 2, 'Yusuf says, ''I haven''t actually met the family — but I''d be careful about generalising like that. I don''t think it''s really fair on them.''', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Yusuf challenges the comment privately, calmly, and without aggression, framing his disagreement clearly and professionally. This models the GMC''s expectation that doctors challenge discrimination respectfully, even across hierarchies, and protects the dignity of patients who are not in the room to defend themselves.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'Whether the message was, on balance, intended innocently as a friendly suggestion rather than a romantic overture.', 'Of minor importance', 'This is of minor importance because the mentor''s dual role as Maya''s assessor in two weeks creates a structural conflict that makes a one-to-one social meeting problematic regardless of intent. GMC guidance on conflicts of interest and the wider mentorship literature both treat assessor-mentor combinations as inherently problematic, so what the mentor meant by the message changes Maya''s appropriate response only marginally — she should defer or suggest a group/post-assessment alternative either way.', 0),
    (v_s07, 1, 'The power imbalance created by the mentor''s role in formally assessing her at the end of placement.', 'Very important', 'This is very important because the mentor''s role in formally assessing Maya creates a structural conflict of interest. The GMC and most professional bodies are explicit that one-to-one social meetings across active assessment relationships are problematic precisely because they compromise objectivity, fairness, and trust, regardless of intent.', 1),
    (v_s07, 1, 'That Maya does not want to seem rude or ungrateful to a mentor who has been helpful so far.', 'Not important at all', 'This is not important at all because how Maya will be perceived by a mentor who is overstepping a professional boundary is a self-interest concern that should never prevent her from raising or appropriately addressing the situation. The GMC is clear that politeness must not override genuine professional concerns.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Sasha walks with Mr Hopkins back towards the ward, talking calmly about his home and family, and asks the team to consider a Deprivation of Liberty Safeguards (DoLS) referral and review of his care plan.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it manages the immediate situation calmly and with respect for Mr Hopkins''s dignity, while triggering the correct legal and clinical framework. It addresses both the immediate safety concern and the underlying systemic issue, in line with the Mental Capacity Act and GMC guidance on patients lacking capacity.', 0),
    (v_s08, 2, 'Sasha asks two healthcare assistants to physically restrain Mr Hopkins in a chair until the bed manager arrives.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because physical restraint of a patient who is calm and not legally detained is a serious breach of his rights, dignity, and the legal principle of least restriction. Restraint should never be a first response to a mobile patient with dementia who is not in immediate danger to himself or others.', 1),
    (v_s08, 2, 'Sasha walks Mr Hopkins back to his bay, distracts him with a cup of tea, and asks the nursing team to keep watch while she returns to the rest of her ward jobs.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal, because Sasha addresses the immediate situation safely and humanely, which is good. However, she does not initiate any formal review of capacity, deprivation of liberty, or the wider care plan, so the same situation is likely to recur and the underlying legal and care issues remain unaddressed.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 1, 'That if Tara provides assistance and something later goes wrong, she could face questions about her competence.', 'Not important at all', 'This is not important at all because fear of consequences from acting in good faith should not deter a healthcare professional from helping in an emergency. The GMC''s duty to offer help in emergencies, basic ethical practice, and Good Samaritan principles are clear that this self-interest concern is not a relevant factor when a casualty needs help.', 0),
    (v_s09, 1, 'Whether the casualty is at risk of significant deterioration before the ambulance arrives.', 'Very important', 'This is very important because the casualty''s clinical state — and the risk that it will worsen before paramedics arrive — directly determines what Tara should attempt, how urgent the situation is, and whether she stays at the scene to monitor him. Patient safety is always the highest-ranking factor in any response.', 1),
    (v_s09, 1, 'Whether Tara could provide useful first aid within her existing training without exceeding her competence.', 'Important', 'This is important because Tara''s scope of useful action is shaped by what she has actually been trained to do. Acting within competence is appropriate and expected; attempting procedures she has not been trained for could cause harm. This shapes her response significantly without overriding the duty to help in some way.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'Zara likes the post because the case is genuinely interesting and she does not think anyone outside the hospital would know who the patient is.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because engaging with a post that breaches patient confidentiality endorses the breach and increases its reach. GMC confidentiality guidance is clear that identifiable patient information must not be shared online without consent, and liking the post normalises conduct that could cause real harm to the patient.', 0),
    (v_s10, 2, 'Zara immediately messages her F1 colleague privately, explains that the post could identify the patient, and asks them to take it down that day.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises the concern directly and constructively, before the breach escalates further, and gives the colleague the chance to remedy it themselves. It aligns with GMC duties on confidentiality and on raising concerns about colleagues proportionately and without unnecessary formal escalation as a first step.', 1),
    (v_s10, 2, 'Zara says nothing to her colleague but submits an anonymous complaint to the Trust''s information governance team the following week.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal, because formal reporting to the information governance team is a legitimate route for a confidentiality breach. However, waiting a week and bypassing a direct private conversation first means an ongoing breach is left unaddressed and the colleague receives no immediate feedback. The right channel is used but too late.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Anya laughs the comment off in the moment to avoid awkwardness, then quietly avoids the consultant for the rest of the rotation.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because avoiding the consultant fails to address inappropriate behaviour from a senior colleague and leaves the underlying conduct unchecked, which the GMC''s duty to maintain professional standards requires Anya to challenge. However, the consequences for Anya in the short term are limited and she retains the ability to report later, so it is not catastrophic — unlike a response that would actively cover up or enable misconduct.', 0),
    (v_s01, 2, 'Anya tells the consultant clearly that the comment was inappropriate and reports the incident to her educational supervisor and the Trust''s HR department.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it directly addresses the unprofessional behaviour, uses the correct institutional channels, and aligns with the GMC''s expectation that doctors challenge behaviour that undermines a safe and respectful working environment. Reporting also protects other colleagues who may be experiencing similar conduct.', 1),
    (v_s01, 2, 'Anya posts a vague warning about the consultant on a closed messaging group of fellow foundation doctors so that they know to be cautious around him.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because informal peer warnings bypass proper reporting routes, risk damaging a colleague''s reputation without due process, and breach professional standards around how concerns should be raised. The consequences are limited because the message is in a closed group rather than public, but the action neither resolves the harassment nor protects Anya — formal reporting is required instead.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'That the photograph would be educationally useful for medical students learning suturing technique.', 'Important', 'This is important because educational value is a legitimate consideration that can justify photography in clinical settings under proper consent and storage processes. It is not very important on its own, however, because educational benefit cannot override the patient''s right to consent or the requirement to use Trust-approved devices and storage — the educational case must be weighed against, not substituted for, those duties.', 0),
    (v_s02, 1, 'Whether the patient consented to having images taken on a personal device for teaching purposes.', 'Very important', 'This is very important because the GMC and Trust policies require explicit, specific consent for clinical photography, and consent for surgery does not extend to images stored on personal devices. Acting without that consent breaches confidentiality and patient autonomy and could result in fitness-to-practise consequences, so it must determine whether the photo is taken at all.', 1),
    (v_s02, 1, 'Whether Theo''s phone is usually kept secure and not seen by family members at home.', 'Of minor importance', 'This is of minor importance because day-to-day phone security is tangentially relevant to data protection but does not address the core problems: lack of consent and the use of a non-approved device. Even a fully secure personal phone would not make the photograph appropriate, so this consideration cannot drive the decision.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Tariq raises the concern with his clinical tutor at the next teaching day in two days'' time, framing it as something he overheard.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising the concern with an educational supervisor is a legitimate route for a student, but a two-day delay is too long for a possible controlled drug diversion that may be an active patient safety risk. The action is on the right side of the spectrum but the timing should be the same day, ideally to a senior on the ward.', 0),
    (v_s03, 2, 'Tariq decides not to act because the nurses are senior to him and clearly already aware of the issue.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the GMC requires all members of the healthcare team, including students, to act on patient safety concerns regardless of seniority. Assuming someone else will deal with it ignores the duty to raise concerns, and missing controlled drugs may indicate diversion, impairment of a clinician, or under-treatment of patients in pain — all serious harms.', 1),
    (v_s03, 2, 'Tariq speaks to the ward sister or charge nurse the same day, explains exactly what he overheard, and asks how the concern is being handled.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises a serious patient safety concern through the appropriate local channel, in a timely way, and without making accusations beyond what Tariq actually witnessed. It respects his role as a student while fulfilling the GMC duty to raise concerns about possible drug diversion or controlled drug irregularities.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Priya decides it would be rude to interrupt and assumes the supervisor must have obtained verbal consent during the consultation.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because proceeding on assumption when documented consent is absent carries serious legal and clinical risk. Valid consent is a prerequisite for any clinical procedure under GMC and GDC standards, and assuming it has been obtained is not an acceptable substitute — especially when the relevant documentation is demonstrably missing.', 0),
    (v_s04, 2, 'Priya quietly says, ''Sorry to interrupt — I noticed the consent form hasn''t been signed. Shall we check before we start?''', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Priya raises the concern at the only moment it can be acted on, in a respectful and non-confrontational way. Consent is a core clinical and legal requirement, and a dental student is right to flag an apparent omission regardless of seniority — this is exactly the kind of patient safety issue all team members are expected to speak up about.', 1),
    (v_s04, 2, 'Priya waits until the procedure is complete, then raises the unsigned consent form with the supervisor in private.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because raising the concern with the supervisor afterwards is appropriate professional behaviour and ensures the issue is addressed. However, a procedure has already been performed without properly documented consent, which is the harm that speaking up beforehand would have prevented. The principle is right; the timing is wrong.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 1, 'That Dr Holloway has not previously been offered money by patients or families during her career.', 'Not important at all', 'This is not important at all because the novelty of the offer has no bearing on the professional response required. The duty to refuse inducements and to allocate clinical priority on clinical grounds applies identically whether this is the first offer or the hundredth, so personal experience cannot factor into the decision.', 0),
    (v_s05, 1, 'Whether the patient genuinely needs to be seen sooner on clinical grounds.', 'Very important', 'This is very important because the GMC requires that clinical priority is determined by clinical need, not by financial inducement. The offer should be refused regardless, but the patient''s actual condition still needs to be assessed and, if she should be seen sooner on clinical grounds, that decision should be made and documented separately on its merits.', 1),
    (v_s05, 1, 'Whether refusing the money politely is enough on its own, or whether the offer must also be formally documented and reported.', 'Very important', 'This is very important because GMC probity duties and Trust policy require offers of financial inducement to be formally documented and reported, not merely refused. Failing to record the offer leaves no institutional record, removes protection against later misunderstanding or accusation, and means the family could try the same approach with another clinician unnoticed. The procedural question therefore directly determines what action Dr Holloway must actually take, not just how she handles the moment.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Hannah politely says, ''Sorry to interrupt — would you mind washing your hands first? I noticed they didn''t get done between patients,'' before her supervisor begins.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises the safety concern in real time, before the next patient is exposed, in a respectful and non-confrontational way. The GMC and equivalent dental regulator (GDC) standards require all team members to act on infection control breaches regardless of seniority, and the wording is calm enough to preserve the working relationship.', 0),
    (v_s06, 2, 'Hannah waits until lunchtime and asks her supervisor in private whether he intended to skip handwashing for that patient.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising it privately later is more comfortable but does not protect the patient who has already been seen. The right principle (raising the concern) is applied with the wrong timing for an immediate safety issue — speaking up before the patient is touched would have been the correct response.', 1),
    (v_s06, 2, 'Hannah says nothing because her supervisor is far more experienced than she is and presumably knows what he is doing.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because patient safety duties are not waived by hierarchy, and infection control failures can cause direct, serious harm to patients. Deferring to seniority over a clear breach of policy is precisely the failure mode that GMC and GDC guidance warn against, and inaction here would allow a preventable risk to materialise.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That Lily may genuinely be at risk of harming a patient or behaving unprofessionally during the examination.', 'Very important', 'This is very important because patient safety is the highest professional priority, and a student attending a real-patient examination while apparently under the influence of alcohol creates a direct risk of harm and a clear fitness-to-practise concern. This consideration must determine the response — Owen has a duty to act before the examination starts.', 0),
    (v_s07, 1, 'That Lily and Owen have been close friends since their first week of medical school.', 'Not important at all', 'This is not important at all because personal friendship cannot override the duty to act on a patient safety concern. Allowing the friendship to soften or delay Owen''s response would itself be a professional failure, and the GMC is explicit that personal relationships do not modify professional obligations.', 1),
    (v_s07, 1, 'How likely the supervising clinician is to notice Lily''s intoxication if Owen does nothing.', 'Of minor importance', 'This is of minor importance because the chance that someone else might catch the problem is a marginal practical factor, but it cannot replace Owen''s own duty to raise the concern. Relying on detection by another person is a form of inaction dressed up as judgement — the question is what Owen should do, not what others might do.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Devon agrees not to mention it on the basis that it is Paige''s choice and her risk to take.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because framing academic dishonesty as a private choice ignores Devon''s own duty of integrity and risks normalising misconduct, but the consequences of his inaction are limited and reversible — Paige can still be challenged later or self-correct. It is the wrong response, but not on the same level as actively helping or covering up.', 0),
    (v_s08, 2, 'Devon strongly encourages Paige to rewrite the work in her own words and warns that he cannot stay silent if she submits it as it stands.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it gives Paige a chance to put the situation right herself, is honest about Devon''s own position, and respects the principles of integrity that apply to everyone in the cohort. It tries to resolve the issue locally before any escalation, which is the correct first step for an academic conduct concern of this nature.', 1),
    (v_s08, 2, 'Devon publicly mentions the situation in the class WhatsApp group to discourage others from doing the same.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it publicly identifies and humiliates Paige, breaches what was shared in confidence, and substitutes peer shaming for the proper academic conduct process. Even though the underlying concern is legitimate, the method causes disproportionate reputational harm and short-circuits institutional procedures that exist to ensure fair handling.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 1, 'How long the foundation doctor has already been on shift and how busy the rest of the ward round is.', 'Of minor importance', 'This is of minor importance because workflow pressure is a real practical factor but is the wrong driver for a decision about how to deliver a cancer diagnosis. Convenience cannot determine the standard of communication offered to a patient, though it may legitimately influence how other tasks are sequenced around the conversation.', 0),
    (v_s09, 1, 'Whether using a family member as interpreter risks information being filtered, softened, or misunderstood at a critical moment.', 'Very important', 'This is very important because the accuracy and completeness of the information delivered are central to the patient''s right to make informed decisions about her care. Family interpreters frequently soften bad news, omit detail, or insert their own views, all of which compromise informed consent and the patient''s autonomy in life-changing decisions.', 1),
    (v_s09, 1, 'That the daughter has translated at every previous appointment without apparent issue.', 'Not important at all', 'This is not important at all because past use of the daughter as an interpreter does not validate the practice — it may simply mean that earlier conversations were less complex or that errors went undetected. A serious cancer diagnosis raises the stakes substantially, and previous informal arrangements cannot substitute for a professional interpreter when the consequences of miscommunication are this significant.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'After the operation, Olusola gently asks Mr Yates whether he plans to follow the needlestick injury protocol and offers to find the relevant paperwork.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises the issue with the colleague directly, respectfully, and at a moment when it can practically be acted on, while supporting him to follow occupational health policy. Needlestick injuries require timely post-exposure assessment and possible prophylaxis, and Olusola''s offer of help removes a common excuse for delay.', 0),
    (v_s10, 2, 'Olusola assumes Mr Yates knows what he is doing and writes the incident off as none of her business.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because the duty to look out for colleagues'' wellbeing applies to students too, and silence may allow a serious occupational exposure to go untreated. The consequences are limited because Mr Yates is an autonomous adult and the patient is not directly endangered by Olusola''s inaction, but the response still falls short of professional expectations.', 1),
    (v_s10, 2, 'Olusola mentions the incident to her clinical tutor at her weekly debrief the following Monday.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising the concern with the clinical tutor is a legitimate channel, but the timing is far too late — needlestick post-exposure prophylaxis is most effective within hours of the injury. The action is on the right side of the spectrum but the delay means the most important window for action has already closed.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Olamide says nothing in the moment but reports the incident to the placement coordinator the next morning, without speaking to the student first.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because reporting the matter through the placement coordinator addresses the probity issue, but bypassing direct conversation with the student misses the chance to address it constructively in the moment and feels disproportionate as a first step for a one-off observation. GMC professionalism guidance encourages addressing concerns about a colleague through direct conversation where it is safe and reasonable to do so before formal escalation.', 0),
    (v_s01, 2, 'Olamide tells the student privately that taking the supplies isn''t acceptable and asks them to put everything back before leaving the cupboard.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it directly addresses the probity issue in a private and respectful way, gives the student the opportunity to correct the behaviour, and aligns with GMC expectations of honesty, integrity, and acting promptly when professional standards are being breached. Direct conversation as a first step is consistently the most appropriate response to a peer-level concern of this kind.', 1),
    (v_s01, 2, 'Olamide says nothing and decides the items are inexpensive enough to overlook.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because, although the immediate financial value is small, the student''s behaviour is a probity breach that Olamide has a professional duty to address. GMC guidance is clear that future doctors must be honest and act with integrity regardless of the value of items involved. The lasting consequences of one instance of inaction here are limited, however, which is why it does not reach the most extreme rating.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'That Mark might face a more serious penalty if Tariq refuses to corroborate the certificate.', 'Not important at all', 'This is not important at all because Tariq is not responsible for shielding Mark from the natural consequences of his own dishonesty, and the prospect of a harsher penalty for Mark cannot justify Tariq''s participation in fraud. Allowing the wrongdoer''s potential punishment to drive the decision would invert the ethical reasoning entirely: the right course is determined by Tariq''s own duty of honesty and integrity, not by what happens to Mark if he refuses to help cover the fraud up.', 0),
    (v_s02, 1, 'That helping verify a false medical certificate would amount to fraud against the university.', 'Very important', 'This is very important because participating in fraud is a serious offence with significant academic, professional, and potentially legal consequences. Integrity and honesty are core principles that any future application to medicine, dentistry, or another regulated profession depends on, and Tariq must take this consideration into account above almost anything else when deciding how to respond.', 1),
    (v_s02, 1, 'That Mark and Tariq have shared a flat as good friends for two years.', 'Not important at all', 'This is not important at all because personal friendships should never override basic principles of honesty and integrity. The strength of a relationship does not justify participation in fraud, and a true friend would not place Tariq in a position that requires him to compromise his integrity. Personal loyalty is a classic UCAT trap that should be excluded from professional and ethical decision-making.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Aileen explains that she will complete the notes now but must date them today and mark them as a late entry, then offers to discuss the audit issue with the registrar afterwards.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it produces honest, accurately dated records as required by GMC guidance on probity and good record-keeping, while professionally addressing the registrar''s underlying concerns about the audit. Honest documentation protects patient safety, supports continuity of care, and respects the integrity of the audit process — all of which are non-negotiable professional duties.', 0),
    (v_s03, 2, 'Aileen says nothing in the moment but quietly dates the notes correctly today, hoping the registrar won''t check.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because, although Aileen produces honest documentation, she avoids dealing with a senior colleague''s request for falsification. The right outcome is achieved on the records, but the unprofessional request remains unchallenged, which could leave the registrar believing she complied and could allow similar requests to be made of other junior doctors. Direct, respectful clarification would be more appropriate.', 1),
    (v_s03, 2, 'Aileen agrees and dates the entries Saturday, reasoning that the registrar is more senior and presumably knows the right approach.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because backdating records is dishonest, breaches GMC principles of probity and accurate record-keeping, could mislead the audit, and could ultimately harm patient safety and constitute fraud. Seniority does not justify dishonesty, and the F1 has a professional duty to refuse instructions that compromise integrity, no matter who is asking.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Halima refuses to engage at all, telling the patient that this is between him and the GP.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because, although declining to engage avoids the risk of giving incorrect information, it misses an opportunity to support honest dialogue and reassure the patient that the GP can address his concerns. Patients deserve a respectful response from any healthcare team member they speak to. The harm here is limited because Halima is not actively misleading him, which keeps it short of the most extreme rating.', 0),
    (v_s04, 2, 'Halima honestly says that medical evidence supports vaccination, mentions the GP is best placed to discuss it in full, and offers to fetch the GP so the conversation can continue properly.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it is honest, stays within Halima''s scope as a medical student, and supports the patient by reconnecting him with the GP, who can address his concerns properly. It aligns with GMC guidance on being open and honest, working within one''s competence, and supporting patient understanding and autonomy without overstepping into independent counselling.', 1),
    (v_s04, 2, 'Halima agrees with the patient that ''doctors don''t always tell you everything'' and shares some invented doubts about routine vaccinations to seem trustworthy.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it is dishonest, undermines colleagues, risks the welfare of the patient''s child, and could contribute to broader vaccine hesitancy. It violates GMC core duties of honesty and acting in patients'' best interests, and it goes far beyond a medical student''s scope of practice into independent — and in this case, fabricated — clinical advice.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 1, 'That accepting could blur professional boundaries and increase the risk of inappropriate contact.', 'Very important', 'This is very important because maintaining clear professional boundaries with current and former patients is a core GMC requirement. Given the patient''s previous attempts to ascertain Niamh''s relationship status, accepting carries a real risk of further inappropriate contact and could undermine her ability to provide objective care if he becomes a patient again. This is precisely the type of factor that should drive Niamh''s decision.', 0),
    (v_s05, 1, 'That Niamh found him pleasant during the admission and is curious about his life now that he has recovered.', 'Not important at all', 'This is not important at all because personal interest in a former patient''s life should never drive a professional boundary decision. GMC guidance is explicit that doctors must not pursue personal relationships with patients or use access gained through care to engage with them socially. This is a self-interested motivation that has no legitimate place in the decision.', 1),
    (v_s05, 1, 'That declining the request might come across as rude or upset him.', 'Of minor importance', 'This is of minor importance because, although Niamh can choose to decline politely, the patient''s potential emotional reaction to a professional boundary should not determine whether the boundary is maintained. Patients are not entitled to social access to their treating clinicians, and a brief, professional approach to declining is sufficient. The factor has some bearing on tone but not on the substantive decision.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'Riya warmly declines, explains that performing extractions outside a supervised clinical setting would be unsafe and outside her scope, and helps him find a dental urgent care contact for next-day advice.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it stays clearly within Riya''s scope of practice, communicates warmly so the relationship is preserved, and signposts to safe, regulated care. GDC and GMC professional standards both require trainees to know and respect the limits of their competence and to support patients in accessing proper care rather than improvising outside a clinical environment.', 0),
    (v_s06, 2, 'Riya refuses for herself but tells him ''any of us could do it really'' and suggests he ask another dental student friend instead.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because, although Riya correctly declines, she undermines the principle of safe practice by suggesting that another dental student could perform the procedure outside a regulated clinical environment. This could encourage him to seek unsafe care from someone else. The immediate harm of saying it is limited, which keeps it short of the most extreme rating, but it sends a misleading message about scope and safety.', 1),
    (v_s06, 2, 'Riya agrees to take a quick look in the kitchen and proceeds with the extraction if the tooth appears straightforward.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because performing a clinical procedure outside a supervised, regulated setting carries serious risks: inadequate sterilisation and infection control, no resuscitation backup, no documentation, no proper informed consent process, and potential for serious complications. It would breach GDC standards on scope of practice and could amount to practising outside competence.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That the workload is now distributed unfairly across the rest of the group.', 'Important', 'This is important because unequal contribution affects the group as a whole and the quality of the deliverable, and Mike will need to balance Sade''s wellbeing with the legitimate concerns of other group members. While not the most pressing factor in the moment of disclosure, ignoring it would be unfair to those picking up the slack and would store up problems for the team.', 0),
    (v_s07, 1, 'That Sade shared this in confidence and may not want it disclosed to the rest of the group.', 'Very important', 'This is very important because Sade has trusted Mike with sensitive personal information about her financial circumstances. Breaching that confidence without good reason could damage their relationship, undermine her willingness to seek help in future, and is contrary to the basic principle of respecting confidentiality where there is no overriding safeguarding or safety concern. Mike must factor this in heavily before saying anything.', 1),
    (v_s07, 1, 'That Mike doesn''t want to seem uncaring if he raises Sade''s situation in the next group meeting.', 'Not important at all', 'This is not important at all because Mike''s concern about how he will appear to others is a self-interested consideration that should not determine how he handles a friend''s disclosure. Personal reputation considerations should never override the genuine interests of the people involved or the duty to act fairly and respectfully toward both Sade and the wider group.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Conor laughs awkwardly to ease the tension and hopes the moment passes.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because laughing in response to a racist remark normalises it and signals to Dr Adesanya that Conor is not on his side. GMC guidance and basic professional standards require all healthcare team members not to endorse discriminatory behaviour, and laughing along is a form of complicity that can cause real and lasting harm to the colleague affected.', 0),
    (v_s08, 2, 'Conor immediately tells the patient that his comment was racist and instructs him to leave the clinic.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because, although the instinct to challenge racism is right, instructing a patient to leave is well outside the scope of a third-year medical student. The action could escalate the situation, undermine Dr Adesanya''s authority in handling his own clinic, and may not reflect how the consultant himself wishes to address the incident. The intention is good but the action is misjudged for Conor''s role and stage of training.', 1),
    (v_s08, 2, 'Conor mentions the incident to his clinical tutor at the end of the placement week, without saying anything to Dr Adesanya in the meantime.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising the incident with the clinical tutor is a constructive step that supports institutional accountability, but leaving it until the end of the week and without checking in with Dr Adesanya means Conor misses the chance to offer immediate support to the colleague affected and to find out how Dr Adesanya himself wishes the matter to be addressed. A short, supportive private check-in with the consultant should usually come first.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 2, 'Esi agrees and writes the reference, including her concerns about Marcus''s reliability and attendance, without speaking to him about it first.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Esi''s reference is honest, which protects the recruiting panel and is consistent with GMC duties of probity. However, blindsiding Marcus by writing critical points he has not been told about is unprofessional courtesy: she should let him know honestly that she cannot give him a strong reference so he can choose to ask someone else instead. The outcome is honest, but the approach to a colleague is suboptimal.', 0),
    (v_s09, 2, 'Esi declines and explains honestly to Marcus that, given her observations of his attendance, she doesn''t feel able to give him a strong reference, and suggests he ask someone else.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it is honest with both Marcus and the recruiting panel, respects Marcus''s autonomy to seek another referee, and avoids producing a reference that would mislead. It aligns with GMC principles of probity and accurate references, and treats Marcus with respect even though the answer is not what he hoped for. This is the textbook professional approach to a difficult reference request.', 1),
    (v_s09, 2, 'Esi agrees and writes a reference focused only on Marcus''s clinical strengths, omitting any mention of his reliability or attendance issues.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because misleading a recruiting panel through deliberate omission is dishonest and breaches GMC guidance on writing accurate, honest references. It could lead to Marcus being placed in a role where his reliability matters to patient safety or to colleagues, and it is unfair to other applicants who may be passed over because of an inaccurately positive picture of him.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 1, 'That refusing might make their friendship feel awkward for a while.', 'Not important at all', 'This is not important at all because the temporary social discomfort of declining a request that involves academic misconduct should never determine an ethical decision. Friendships are not damaged by maintaining honest standards, and any awkwardness is a personal cost that does not justify breaching the rules of the assessment. Avoiding awkwardness is a self-interested motivation that has no legitimate place here.', 0),
    (v_s10, 1, 'That if their note-sharing were discovered, both Yusuf and Lara could face serious academic penalties.', 'Of minor importance', 'This is of minor importance because, although the risk of being penalised is a real practical consideration, fear of getting caught is a self-interested factor that should not be the primary driver of an integrity decision. The principled reason to refuse is that sharing notes is dishonest collusion that breaches the assessment rules regardless of whether anyone finds out. The possibility of penalty has some bearing as a secondary practical consideration but is clearly subordinate to the rules-and-honesty factor itself.', 1),
    (v_s10, 1, 'That the assessment guidance explicitly forbids sharing notes between students.', 'Very important', 'This is very important because the assessment rules are explicit and binding, and acting against them is a deliberate breach of academic integrity. Following clear rules in academic assessments is fundamental to honesty, fairness to other students, and Yusuf''s standing as a student of integrity in his discipline. This factor should weigh heavily on his decision.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Dr Osei agrees not to tell Mrs Croft and arranges to speak with the daughter again the following day to decide together what to share.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because withholding a diagnosis from a patient with capacity in order to protect a family member''s preferences directly breaches the GMC principle of respect for autonomy and informed consent. Patients are entitled to information about their own health; a family member''s request cannot override this right, and agreeing to conceal the diagnosis leaves Mrs Croft unable to make decisions about her own care.', 0),
    (v_s01, 2, 'Dr Osei explains to the daughter that he understands her concern, but that the decision about what Mrs Croft is told rests with Mrs Croft herself, and he suggests meeting with Mrs Croft together to explore what she wants to know.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it recognises the family''s distress sensitively while maintaining the patient-centred principle that a competent adult controls what information she receives about her health. Inviting a conversation that includes both Mrs Croft and the family is the partnership-based approach the GMC''s guidance on breaking bad news describes.', 1),
    (v_s01, 2, 'Dr Osei goes ahead and tells Mrs Croft her diagnosis alone in her bay, because the registrar told him to do it and he does not want to delay her care.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because informing a patient of their diagnosis respects their autonomy and is the right underlying action. However, delivering a terminal diagnosis in a shared bay without privacy, without resolving the family''s concerns first, and without adequate preparation fails the GMC''s duty to break bad news sensitively and in appropriate surroundings. The intent is correct but the execution causes preventable distress.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'Whether other wards in the hospital appear to be similarly understaffed at night.', 'Of minor importance', 'This is of minor importance because while a hospital-wide pattern might inform how Bryony escalates her concerns, it does not change her duty to raise what she has personally witnessed. Other wards being similarly affected does not make the situation on her ward less risky to those patients. A wider problem might support a stronger case but is not central to her decision.', 0),
    (v_s02, 1, 'Whether the staffing levels are placing patients at risk of delayed care or harm.', 'Very important', 'This is very important because patient safety is the highest priority in the GMC framework (Good Medical Practice, Domain 2). If staffing levels are causing delayed observations, late medications, or slow responses to call bells, that is a direct safety risk that Bryony has a professional duty to act on regardless of her seniority.', 1),
    (v_s02, 1, 'That Bryony is only on the ward for another two weeks before her placement ends.', 'Not important at all', 'This is not important at all because the length of time remaining on a placement should never determine whether to raise a concern about patient safety. Reasoning of this kind reflects personal convenience and the desire to avoid awkwardness, neither of which is a legitimate factor when patient welfare is at stake (GMC duty to raise and act on concerns).', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Dr Halstead provides a brief summary of Mrs Owen''s condition, on the basis that the caller has identified himself as her husband and seems genuinely concerned.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the doctor cannot verify the caller''s identity or whether the patient has consented to disclosure, and sharing clinical information without consent breaches confidentiality (GMC Confidentiality guidance). Apparent sincerity is not a substitute for the patient''s express consent, and disclosing to someone falsely claiming to be a relative could cause serious harm.', 0),
    (v_s03, 2, 'Dr Halstead explains that he cannot share information without the patient''s consent, takes the caller''s number, and offers to discuss with the patient whether she wishes him to be updated.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it protects confidentiality, treats the caller respectfully, and creates a route to keep the family appropriately informed if the patient consents (GMC Confidentiality, on disclosures with consent). It directly addresses the core issue — verifying consent — without being unnecessarily abrupt or unhelpful.', 1),
    (v_s03, 2, 'Dr Halstead asks the caller to confirm Mrs Owen''s date of birth and address as identification, then shares some clinical information once those details match the record.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because confirming personal details is not equivalent to the patient consenting to disclosure, and family members would commonly know these facts. Dr Halstead is making an effort to verify identity, but the verification is weak and bypasses the patient''s right to control disclosures (GMC Confidentiality). The consequences are limited if the caller is genuinely the spouse, but the principle has still been breached.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Deepa accepts the explanation and says nothing further, reasoning that her colleague is only reading and not changing anything.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because accessing patient records without a clinical justification is an unauthorised data access breach under GDPR and GMC confidentiality guidance, regardless of whether records are altered. Accepting the explanation and staying silent allows an ongoing breach to go unreported and sends the message that curiosity-driven record access is acceptable.', 0),
    (v_s04, 2, 'Deepa tells her colleague clearly that accessing records without a clinical reason is a confidentiality breach, asks her to log out now, and reports the incident to the information governance lead that day.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it stops the breach in real time and then uses the correct institutional route. GMC confidentiality guidance and data protection law both require that such breaches are reported, not just verbally challenged, and the combination of immediate intervention and formal reporting addresses both the immediate and ongoing risks.', 1),
    (v_s04, 2, 'Deepa makes a note of what she saw and raises it with her educational supervisor at their next meeting in two days.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal, because raising the concern with a supervisor is a legitimate channel and preserving a note of what occurred is good practice. However, waiting two days means a known confidentiality breach remains unaddressed for that period. A more immediate report to the information governance lead would have been more proportionate given the seriousness of an unauthorised record access.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 2, 'Yara amends the treatment plan herself to reflect tooth 27 and adds a note in the chart so the appointment can proceed as planned next week.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because altering a record signed off by a supervising clinician without their knowledge is dishonest, falls outside the dental student''s authority, and corrupts the clinical record (GMC Good Medical Practice on records, and equivalent GDC standards on probity). It also risks the wrong tooth being treated if Yara is mistaken about which tooth was discussed, since no second opinion has been obtained.', 0),
    (v_s05, 2, 'Yara waits until tomorrow morning to raise the issue with her supervising dentist when they next meet at the clinic.', 'Appropriate, but not ideal', 'This is appropriate but not ideal because Yara is identifying the discrepancy and intending to raise it with the right person, which respects the supervisory chain. With the next appointment a week away, waiting until the next day is acceptable rather than urgent — but contacting her supervisor sooner would be more proactive and reduce the risk of further entries being made before the correction. The action is reasonable but slightly delayed.', 1),
    (v_s05, 2, 'Yara raises the discrepancy with her supervising dentist immediately so that it can be reviewed, the patient contacted if needed, and the records corrected before the next appointment.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it raises the discrepancy promptly with the person responsible, supports correction of the record, and ensures the patient is contacted if necessary before the next appointment (GMC duty to be open and to keep accurate records). It addresses the core issue directly and within Yara''s scope as a student.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 1, 'Whether other students may also have been sent the photograph and could gain an unfair advantage.', 'Not important at all', 'This is not important at all because the prevalence of the leak does not change whether Lucy participating would itself be cheating. Honesty and academic integrity are non-negotiable for medical students (GMC Achieving Good Medical Practice for medical students), and viewing leaked exam material is dishonest regardless of who else is doing it. Reasoning that depends on what others are doing is a hallmark of compromised integrity rather than a legitimate factor in an ethical decision; Lucy''s choice must rest on her own conduct, not the conduct of others.', 0),
    (v_s06, 1, 'That Tomasz has always been a reliable friend and Lucy does not want to upset him.', 'Not important at all', 'This is not important at all because personal loyalty cannot determine whether to engage in academic misconduct (GMC Maintaining Trust principles applied to professional training, and university academic integrity policies). Friendship is a self-interested consideration with no bearing on whether using leaked material would be dishonest.', 1),
    (v_s06, 1, 'Whether viewing the photograph would constitute academic misconduct under university regulations.', 'Very important', 'This is very important because honesty and integrity are fundamental to professional practice, and academic misconduct in medical training has serious consequences including potential fitness to practise concerns (GMC Achieving Good Medical Practice for medical students). Whether the action is dishonest is the central question and must be the deciding factor for Lucy.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That signing the form as requested would be a dishonest record of her attendance.', 'Very important', 'This is very important because honesty in record-keeping and attendance is a core professional duty, and falsifying records is a fitness to practise issue regardless of who has asked for it (GMC Good Medical Practice, on probity and being open). The dishonesty itself is the central concern and must drive Niamh''s decision.', 0),
    (v_s07, 1, 'Whether the consultant might give her a poor placement evaluation if she refuses.', 'Not important at all', 'This is not important at all because fear of an adverse evaluation is a self-interested concern that should never override the obligation to be honest. Acting on this fear would itself be a serious professional failing. GMC guidance is clear that probity comes before personal advantage, and pressure from a senior does not legitimise dishonesty.', 1),
    (v_s07, 1, 'Whether the medical school''s attendance policy allows clinic time to be recorded when a clinic is cancelled or stood down.', 'Important', 'This is important because if the school has a legitimate route to record clinic time when sessions are stood down — for example by counting it as study time or allowing an alternative entry — Niamh may be able to comply with attendance requirements honestly. Knowing the policy directly affects how she addresses the consultant''s request without compromising integrity.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'Femi documents the reported fall in the notes, examines Mr Reid for any injury, completes an incident form, and lets the senior nurse on duty know what happened.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because patient safety is paramount and incidents must be properly documented and reviewed regardless of perceived severity (GMC Good Medical Practice, Domain 2, and incident reporting requirements). It also ensures Mr Reid is reassessed for any injury and that the senior nurse can take any wider action that is needed in response to the fall.', 0),
    (v_s08, 2, 'Femi assumes that the night team must have decided the fall was too minor to record and does not raise it further.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because every patient fall must be documented; assumptions about what other staff have decided do not discharge Femi''s own duty (GMC Good Medical Practice, duty to keep accurate records and act on safety concerns). Failing to document also prevents proper review of staffing, environmental factors, or trends, and could harm the patient if related issues are missed.', 1),
    (v_s08, 2, 'Femi mentions the issue casually to the consultant during the ward round but takes no further action himself.', 'Inappropriate, but not awful', 'This is inappropriate but not awful because raising the issue with the consultant is a reasonable instinct, but Femi has not actually completed any of the necessary actions himself: examining the patient, documenting the fall, or completing an incident form. The consequences are likely limited if the consultant follows up, but Femi has not fulfilled his own clinical responsibility for the patient in front of him.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 1, 'That Dr Patel personally disagrees with the religious reasoning behind the refusal.', 'Not important at all', 'This is not important at all because a clinician''s personal views about the reasoning behind a patient''s decision must not influence respect for their autonomous choice (GMC Decision Making and Consent, and Personal Beliefs and Medical Practice). Provided the patient has capacity and is informed, her reasoning is hers alone and Dr Patel''s discomfort is irrelevant to the clinical course of action.', 0),
    (v_s09, 1, 'The wishes of the patient''s family members, who are asking the team to override the refusal.', 'Of minor importance', 'This is of minor importance because the wishes of family members do not override a capacitous patient''s decision, but acknowledging family distress is part of compassionate care and may need sensitive communication and support (GMC Communication and Partnership). The clinical decision is unaffected, but the family interaction matters in a limited way as part of overall care.', 1),
    (v_s09, 1, 'That the patient has capacity and has made an informed, autonomous decision.', 'Very important', 'This is very important because respect for autonomy is a foundational ethical principle, and a competent adult''s informed refusal of treatment must be respected even when clinicians disagree (GMC Decision Making and Consent). This factor is the central consideration that determines the team''s lawful and ethical course of action.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'Remi attempts the procedure alone because the registrar is experienced and has deemed it appropriate, and the patient needs the fluid drained.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because performing an invasive procedure without having been trained, supervised, or signed off as competent places the patient at direct risk of serious harm. GMC Good Medical Practice is clear that doctors must recognise and work within the limits of their competence; the seniority of the person asking does not override this duty.', 0),
    (v_s10, 2, 'Remi tells the registrar clearly that he has not been signed off to perform pleural aspirations and asks the registrar to either do it before leaving or arrange for another trained clinician to attend.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Remi recognises the limits of his competence, declines an unsafe task, and constructively identifies a workable alternative rather than simply refusing. This models the GMC principle that doctors must work within their competence and ask for support when asked to act beyond it — doing so is professionalism, not weakness.', 1),
    (v_s10, 2, 'Remi prepares the patient and equipment but waits until he can reach a senior colleague by phone to talk him through the procedure before inserting the needle.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because Remi is attempting to address the competence gap by seeking real-time guidance, which shows some awareness of his limits. However, performing an invasive procedure for the first time without direct supervision, guided only by telephone, remains unsafe and inconsistent with the standard of oversight required for a first-time proceduralist. The right action was to refuse and escalate, not to attempt with remote guidance.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Aisha asks the senior house officer who is also covering the ward what they think she should do before responding to the registrar.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because seeking peer input is a reasonable instinct when feeling out of one''s depth, but the SHO has no more authority over the discharge plan than Aisha herself. The action delays a decision that affects patient safety without progressing it. A better response would be to push back to the registrar directly or escalate to the consultant, both of whom are accountable for the decision.', 0),
    (v_s01, 2, 'Aisha tells the registrar she is not comfortable discharging Mrs Olufemi without the CT result, and asks the registrar to discuss the plan with the consultant before any decision is made.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because patient safety is the highest priority and Aisha is right to refuse to act on a decision she believes may be unsafe. GMC Good Medical Practice requires doctors to raise patient safety concerns, escalate appropriately, and ensure the senior decision-maker is involved before a potentially risky discharge.', 1),
    (v_s01, 2, 'Aisha completes the discharge paperwork and writes in the notes that the registrar instructed her to send Mrs Olufemi home.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because documenting that the registrar instructed the discharge does not transfer responsibility — Aisha remains accountable for her own clinical actions. Discharging a patient with a possible pulmonary embolism before investigations are complete is a direct patient safety risk and breaches the GMC duty to protect patients.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'That the patient is unlikely to be travelling on this particular bus route.', 'Of minor importance', 'This is of minor importance because while the chance of the patient herself being on this route is small, confidentiality is breached the moment identifiable information is shared in a public space — regardless of whether the patient is present. The route does not change the underlying principle or what Olivia should do.', 0),
    (v_s02, 1, 'That stopping the conversation might cause Ben some embarrassment in front of the other passengers.', 'Not important at all', 'This is not important at all because Ben''s potential embarrassment is a personal-comfort consideration that should never override professional duty. GMC guidance on confidentiality is clear that patient information must be protected; Olivia should act regardless of how Ben might feel about it.', 1),
    (v_s02, 1, 'The risk that the patient could be identified by someone overhearing the details Ben and Olivia are sharing.', 'Very important', 'This is very important because the duty of confidentiality, set out in GMC Good Medical Practice and the GMC''s confidentiality guidance, requires medical students and doctors to avoid sharing identifiable patient information where it can be overheard. Identification risk goes to the heart of why this conversation must stop.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'Tariq drafts a brief note for the GP to look over and sign later in the day, leaving it on the GP''s desk with the patient''s name.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because while Tariq has correctly stopped short of issuing certification himself, drafting a note based on a corridor encounter pre-empts the GP''s clinical assessment and creates a record without proper review. The intention is helpful and the GP retains the option to refuse to sign, so consequences are limited — but it remains a step beyond what a student should be doing.', 0),
    (v_s03, 2, 'Tariq prints a note on the practice''s headed paper, signs it with his own name, and hands it to the patient.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it acts clearly outside the student''s scope of practice and is dishonest in misusing the practice''s headed paper and Tariq''s signature. Sick certification requires assessment and authority that medical students do not have; this kind of documentation fraud is a serious probity breach under GMC standards.', 1),
    (v_s03, 2, 'Tariq explains that as a student he isn''t able to issue sick certification, and offers to speak to reception about an urgent appointment slot or a same-day phone call from the GP.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it is honest about Tariq''s role and limits, supports the patient by directing him to the correct route for assessment, and protects the integrity of clinical certification. It models the GMC principles of recognising one''s limits and being honest while still being genuinely helpful.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Daniel tells the pharmacist that he is too busy to discuss it further and asks them to give the dose as he has prescribed.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it dismisses a clear safety query from another qualified professional and prioritises Daniel''s busyness over a potential prescribing error in an elderly patient on opioids. GMC principles require doctors to take colleagues'' concerns seriously and treat patient safety as the top priority.', 0),
    (v_s04, 2, 'Daniel thanks the pharmacist for raising the concern, looks again at the BNF and the patient''s most recent eGFR, and calls the pharmacist back to confirm or correct the prescription.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it respects the pharmacist''s expertise, takes immediate ownership of the prescribing decision, and uses the most relevant clinical references (BNF, renal function) to recheck. It models good multidisciplinary teamwork and the GMC duty to verify decisions when challenged.', 1),
    (v_s04, 2, 'Daniel emails his consultant asking them to review the prescription when they next come to the ward, and tells the pharmacist the consultant will look at it.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because while Daniel does involve a senior, email and a ''next time on the ward'' timeframe is an inadequate channel for an active safety concern about a high-dose opioid in an elderly patient. The dose may be due before the consultant reads the email, and Daniel has avoided doing his own immediate recheck. Consequences are limited because the pharmacist won''t dispense without resolution — but the action passes the urgency back to others rather than addressing it.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 2, 'Layla puts the sheet safely into her bag and waits until her next placement day, two days away, to return it to the ward in person.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because while Layla is keeping the document secure, the two-day delay means the team has no opportunity to take immediate steps about the data breach (such as informing information governance or affected patients). The right instinct is undermined by avoidable delay; consequences are limited because the document is in safe keeping but still real.', 0),
    (v_s05, 2, 'Layla photographs the sheet to study from realistic patient summaries later, then leaves the original on the bus seat.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because photographing identifiable patient data compounds the original breach by creating further unauthorised copies, and leaving the sheet on the seat means anyone could pick it up. Both actions seriously violate GMC confidentiality duties and data protection law.', 1),
    (v_s05, 2, 'Layla immediately phones the hospital switchboard, asks to be put through to the ward listed on the sheet, and explains that she has found a confidential handover document.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it ensures the document is secured as quickly as possible, allows the ward and information governance team to take immediate action on the breach, and reflects the GMC duty to protect confidentiality and act when breaches occur.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 1, 'That the procedure will be recorded in Hannah''s clinical logbook as a filling she performed, and that she is professionally accountable for what she does.', 'Important', 'This is important because Hannah is professionally accountable for her own clinical actions, regardless of who supervised her. The GDC and GMC frameworks both require students and registrants to act within professional standards; she should consider that her record will reflect this procedure and that she cannot pass responsibility for substandard practice to her supervisor.', 0),
    (v_s06, 1, 'That contradicting the supervisor in front of the child and the child''s parent could be awkward for Hannah.', 'Not important at all', 'This is not important at all because personal awkwardness or social discomfort is a self-interest consideration that must not override patient safety. The duty to act in the child''s best interest applies regardless of how it makes Hannah feel in front of others present.', 1),
    (v_s06, 1, 'Whether using composite material past its expiry date could affect the safety, durability, or biocompatibility of the filling for the child.', 'Very important', 'This is very important because patient safety is the highest professional priority. Materials are given expiry dates for clinical reasons (curing properties, biocompatibility, structural integrity), and using them outside specifications on a child could affect the durability and safety of the restoration.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 2, 'Adam interrupts the healthcare assistant in front of Mrs Whitlock and tells her she is being patronising and should speak to the patient like an adult.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because public confrontation embarrasses the healthcare assistant in front of the patient and other staff, undermines the ward team dynamic, and is likely to add to Mrs Whitlock''s discomfort rather than ease it. GMC guidance explicitly favours private, respectful communication when raising concerns about a colleague''s conduct.', 0),
    (v_s07, 2, 'Adam says nothing because the healthcare assistant is clearly trying to be warm, and confronting her could damage their working relationship on the ward.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because Mrs Whitlock''s dignity is being compromised and Adam has a duty to act, but his inaction here has limited and transient consequences (one interaction). His reasoning — protecting the working relationship — is a poor justification, but the omission isn''t deliberately harmful. The right response is to act, just privately.', 1),
    (v_s07, 2, 'Adam waits until later in the shift, finds the healthcare assistant alone, and gently raises that he noticed Mrs Whitlock seemed uncomfortable being addressed as ''sweetie'', and asks how she might adjust her approach.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it directly addresses the dignity issue with the person who can change their behaviour, does so privately and respectfully (which preserves the working relationship), and reflects GMC principles around treating colleagues with kindness while still raising legitimate professional concerns.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 1, 'That commenting on a consultant''s clinical decisions to a relative could be seen as criticising a colleague without full information.', 'Important', 'This is important because the principle of not commenting critically on a colleague''s management without knowing the full picture is a real professional consideration that shapes how Dr Abubakar should respond. However, it should not prevent him from acknowledging the complaint, expressing empathy, and directing Mr Farrell to the correct process — it affects the content of his response, not whether he engages.', 0),
    (v_s08, 1, 'Whether the formal complaints process has received and acknowledged Mr Farrell''s written complaint within the expected timeframe.', 'Very important', 'This is very important because ensuring formal complaints are received, acknowledged, and tracked is part of the duty of candour and the NHS complaints framework. If the complaint has not been acknowledged as expected, that is itself a process failure that Dr Abubakar can help remedy by directing Mr Farrell to PALS or the relevant patient liaison team. The adequacy of the response to the complaint directly determines what action is needed.', 1),
    (v_s08, 1, 'That other patients and visitors in the corridor may overhear the conversation.', 'Not important at all', 'This is not important at all because the possible discomfort of bystanders cannot determine how a doctor responds to a distressed relative raising a legitimate concern. GMC Good Medical Practice requires compassionate and honest communication with patients and families; whether others can hear the conversation is a peripheral practical consideration that does not bear on the professional duty to engage.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 2, 'Lily accepts the offer and begins posting, adding a brief sponsored disclaimer so that followers can see the commercial relationship.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because a sponsored disclosure meets consumer transparency requirements but does not address the deeper issue: Lily is using her identity as a medical student to lend professional credibility to health claims she has not evaluated and is not qualified to endorse. GMC guidance on social media and probity cautions doctors and students against commercial relationships that could compromise their integrity or mislead the public about the basis of their endorsement.', 0),
    (v_s09, 2, 'Lily declines the offer and raises it with her medical school, noting that the company appears to be targeting medical students specifically.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because declining is the right personal decision and informing the medical school allows the issue to be addressed at institutional level if the company is systematically exploiting students'' professional identities. It reflects the GMC''s guidance on maintaining professional integrity in online spaces and the broader duty to raise concerns that may affect peers.', 1),
    (v_s09, 2, 'Lily accepts the free products for personal use but does not post about them, reasoning that no public claim is being made.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because accepting personal benefits from a company seeking to trade on her medical student identity creates a low-level conflict of interest the GMC warns against, even without any public endorsement. No immediate patient harm occurs, which keeps it short of the most extreme rating, but the acceptance itself falls short of the probity standards expected of healthcare students.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 1, 'The risk that the trolley could be needed for a cardiac arrest call during his shift while drugs are out of date and the contents have not been checked.', 'Very important', 'This is very important because emergency equipment must be in working order at the moment it is needed; out-of-date drugs and unverified stock could directly cost a patient''s life during a cardiac arrest call. Safety considerations of this immediacy and severity always take priority under GMC Good Medical Practice.', 0),
    (v_s10, 1, 'That the previous F1 may have been very busy on Saturday night and run out of time to do the daily check.', 'Of minor importance', 'This is of minor importance because while it provides empathic context for the lapse, it does not change Marcus''s duty to act now — the previous F1''s workload doesn''t make the trolley any safer or unsafer for the next arrest call. It might shape how he raises the issue, but not whether he raises it.', 1),
    (v_s10, 1, 'Whether the gap reflects a wider rota or system issue with daily checks, rather than a one-off lapse.', 'Important', 'This is important because identifying whether this is a system-level problem (rota, staffing, oversight) rather than a single missed check shapes how Marcus reports it. A systemic issue requires escalation to the matron or governance lead so it can be addressed properly, not just a one-off catch-up of the missing checks.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'The dental student tells the parent firmly that everything they have read online is wrong and that they are putting their child''s teeth at risk by refusing the treatment.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because lecturing or confronting a parent in this way is unlikely to change their view and may damage trust, but it does at least surface the dental concern. GMC Good Medical Practice requires effective, respectful communication and partnership with patients and carers, and a confrontational approach undermines this. The action is not ''very inappropriate'' because the student is not lying or ignoring the issue — they are addressing it badly rather than not at all.', 0),
    (v_s01, 2, 'The dental student calmly asks the parent what specifically concerns them about fluoride and offers to bring the supervising dentist over to discuss the concerns before any decision is finalised.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it respects the parent''s autonomy, treats their concerns seriously, and brings the question to the qualified clinician without the student overstepping their role. GMC Good Medical Practice requires students to work within their competence, communicate respectfully, and ensure decisions about a child''s care are made in genuine partnership with informed parents. This response addresses the situation directly while keeping the child''s best interest central.', 1),
    (v_s01, 2, 'The dental student waits until the parent and child have left the surgery and only then mentions the parent''s refusal to the supervising dentist, rather than offering to bring it up while the family is still present.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising the concern with the supervising dentist still ensures the issue is documented, but the chance to address the parent''s concerns and offer the recommended treatment in this appointment is lost. GMC Good Medical Practice emphasises acting promptly when concerns about patient care arise — the delay means the child may leave without recommended preventive care that a more timely conversation could have made possible.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 1, 'That Finn''s recollection may not be fully accurate and there may be a straightforward explanation for the figure Lena has listed.', 'Important', 'This is important because Finn may not have full knowledge of all the hours Lena completed, and it would be unfair to assume dishonesty without first giving her the chance to explain. This shapes how he raises the concern — directly and without accusation — rather than changing whether he raises it at all. A proportionate first step is to ask Lena directly before drawing conclusions.', 0),
    (v_s02, 1, 'Whether providing significantly inaccurate information on a formal application would constitute dishonesty of the kind the GMC and the institution treat as a fitness-to-practise concern.', 'Very important', 'This is very important because misrepresenting verifiable information on a competitive application is a form of academic fraud that the GMC explicitly links to the integrity expected of future healthcare professionals. This is the central question Finn must consider when deciding whether and how to act — the principle of honesty in all professional dealings applies from the outset of training.', 1),
    (v_s02, 1, 'That Lena would be at a competitive disadvantage in the application if she corrected the figure to an accurate one.', 'Not important at all', 'This is not important at all because the competitive disadvantage Lena might face by being honest is not a legitimate reason to allow inaccurate information to stand. Probity requires honesty regardless of personal cost, and concern for a friend''s application outcome is a self-interest consideration that cannot override the fundamental duty to be truthful on formal applications.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 2, 'The medical student waits until later in the day and mentions what they overheard to the practice manager, rather than addressing the conversation while it is happening.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because raising the concern with the practice manager does ensure the issue is dealt with, but the breach is occurring in real time and the most direct way to stop further disclosure is to act in the moment. GMC Good Medical Practice requires confidentiality to be protected actively. The action is not ''very appropriate'' because immediate intervention would have stopped the disclosure sooner.', 0),
    (v_s03, 2, 'The medical student approaches the desk and quietly indicates to the receptionist that the conversation can be overheard by people in the waiting area.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it stops the breach immediately while treating the receptionist with respect and avoiding any public confrontation. GMC Good Medical Practice requires every member of the healthcare team to protect patient confidentiality and to raise concerns where it is being compromised. Quiet, direct intervention is the preferred professional approach — addressing the issue in real time at the lowest level of escalation.', 1),
    (v_s03, 2, 'The medical student does nothing because reception staff are not clinicians and managing their conduct is not the student''s role.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because confidentiality is the responsibility of every member of the healthcare team, including students on placement, and inaction in the face of an ongoing breach allows harm to continue. GMC Good Medical Practice is explicit that confidentiality is a core duty and that concerns must be raised regardless of who is responsible — the ''not my role'' justification is a recognised inaction trap.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'The student agrees to perform the calibration alone so that the lab partner can leave on time, completing the rest of the assessed data collection by themselves.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because the data integrity concern is addressed — the calibration is performed — but the partner is allowed to leave early on assessed work, which raises a small fairness issue and lets the partner avoid responsibility. The student is right to refuse the shortcut, but a better response would involve the partner staying briefly to share the work, which would meet both the integrity and the fairness expectations of academic conduct.', 0),
    (v_s04, 2, 'The student refuses to skip the calibration step and asks the lab partner to help complete it quickly so that they can both leave on time.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it protects the integrity of the data, holds both partners accountable for the work being submitted, and addresses the issue directly without confrontation. GMC Good Medical Practice and the wider duty of integrity in academic and research work require that submitted data be reliable, and this response solves both the safety and the fairness aspects at once.', 1),
    (v_s04, 2, 'The student skips the calibration step and writes in the lab book that calibration was performed, so the report appears complete.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it combines a procedural shortcut that compromises data validity with active falsification of the record, which is academic and research misconduct. GMC Good Medical Practice and the duty of integrity require accurate recording of what was actually done — fabrication of records is among the most serious breaches a student or clinician can commit, regardless of the perceived size of the omission.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 1, 'Whether the patient is able to recognise warning symptoms and seek urgent help if a complication arises after they leave.', 'Very important', 'This is very important because the patient''s safety after discharge depends on whether they can recognise warning signs and access urgent care. Discharge against medical advice is permissible when the patient has capacity and has been informed, but GMC Good Medical Practice and the duty of care still require the F1 to ensure the patient leaves with a safe plan, including knowing when and how to seek help.', 0),
    (v_s05, 1, 'That the consultant surgeon will be unhappy that a post-operative patient is leaving against medical advice during their ward.', 'Not important at all', 'This is not important at all because the consultant''s reaction has no bearing on the patient''s right to make their own decision. GMC Good Medical Practice is clear that respect for patient autonomy and the duty to support informed decisions take precedence over the convenience or preferences of the team. Worrying about how a senior will react is a self-interest consideration that should not drive a clinical decision when a capacitous patient has chosen to leave.', 1),
    (v_s05, 1, 'The specific personal reason the patient gives for needing to leave the ward urgently.', 'Of minor importance', 'This is of minor importance because the patient has capacity and is entitled to make decisions for any reason or no reason at all. The reason could be relevant if it suggested a misunderstanding the F1 might clarify, but otherwise the doctor''s role is not to evaluate whether the personal reason is ''good enough'' — the GMC principle of autonomy means a capacitous patient does not need to justify their choice.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 2, 'The medical student thanks the patient warmly, declines to share a personal number while explaining that personal contact would not be appropriate, and asks if the gift can be shared with the team and recorded in the placement''s gift register.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it maintains the professional boundary, acknowledges the patient''s gratitude warmly, and ensures any gift is handled transparently through normal team and supervisor channels. GMC Good Medical Practice requires clear professional boundaries with patients and openness about gifts that could be perceived as affecting clinical judgement. This response satisfies all three: boundary, dignity, and transparency.', 0),
    (v_s06, 2, 'The medical student politely declines both the personal number and the gift basket but does not mention the gesture to the supervising team.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because the boundary is correctly maintained, but failing to inform the supervisor means there is no record of the gesture or of how it was handled. GMC Good Medical Practice expects openness about gifts and patient interactions, particularly where a patient has tried to extend the relationship beyond clinical care. The student''s choice is reasonable but misses the transparency step.', 1),
    (v_s06, 2, 'The medical student gives the patient their personal number, reasoning that the patient is about to be discharged and is no longer under their care.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it crosses a clear professional boundary by establishing a personal connection with a recently treated patient, which can compromise objectivity, raise safeguarding concerns, and breach professional standards. GMC Good Medical Practice is explicit that personal relationships with current or recent patients are inappropriate, and the rationalisation that the patient is being discharged does not remove the duty — boundaries persist beyond a single episode of care.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 1, 'That raising the concern formally could create awkwardness in the student''s remaining supervision meetings with the supervisor.', 'Not important at all', 'This is not important at all because personal discomfort or awkwardness in a professional relationship cannot be a reason to ignore unfair treatment. Professional values and the GMC''s broader principles around fairness require concerns about equity to be raised regardless of social cost — fearing awkwardness is a recognised self-interest trap that obstructs proper raising of concerns.', 0),
    (v_s07, 1, 'Whether other students in the supervision group share the same concern or have noticed the same pattern of unequal access.', 'Important', 'This is important because corroboration from peers strengthens the case that the disparity is real rather than perception, and signals that the issue is affecting more than one student. Principles of fairness in education emphasise that concerns about supervision are best addressed when supported by collective experience. It is not ''very important'' because the disparity could legitimately be raised on its own merits even without others corroborating.', 1),
    (v_s07, 1, 'Whether the disparity in supervision is having a measurable effect on other students'' progress and final dissertation grades.', 'Very important', 'This is very important because actual harm to other students'' education and outcomes is the central reason such a disparity needs to be addressed, and engages duties of fairness and equity that underpin academic and professional life. GMC Good Medical Practice principles of fairness and treating people equally apply equally to educators, and a measurable effect on outcomes is the strongest justification for formal escalation.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 2, 'The F1 tells the colleague to wash their face and pull themselves together because the team needs them and the shift is about to begin.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it dismisses a colleague in clear distress, ignores potential fitness-to-practise implications, and prioritises the running of the shift over the wellbeing of a peer and over patient safety. GMC Good Medical Practice requires support for colleagues whose performance or health may be affected, and a colleague who is visibly trembling and crying may not be safe to work — pretending otherwise risks both the colleague and patients.', 0),
    (v_s08, 2, 'The F1 quietly sits with the colleague, says they don''t have to talk but are there if they want to, and gently asks whether they feel safe to start the shift.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because it offers compassionate support without forcing disclosure, treats the colleague with dignity, and addresses the patient-safety implication by gently checking whether they feel able to work. GMC Good Medical Practice supports colleagues in distress and requires honest evaluation of fitness to practise — both threads are handled here without confrontation.', 1),
    (v_s08, 2, 'The F1 leaves the changing room without saying anything further so the colleague is not embarrassed by being seen upset.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because the intention to spare the colleague is well-meaning, but ignoring a peer in obvious distress fails the duty of care to colleagues and may also miss a fitness-to-practise concern. GMC Good Medical Practice expects healthcare professionals to support each other, and walking past in this situation prioritises the F1''s own discomfort over the colleague''s needs — it does not cause lasting harm only because the colleague may seek help elsewhere.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 2, 'Isaac says nothing because his supervisor is a qualified dentist with many years of experience and has presumably made a clinical judgement that no X-ray was necessary.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because deferring entirely to seniority when a written clinical protocol has visibly not been followed is a failure to act on a patient safety concern. The GDC and GMC both require all team members, including students, to raise concerns about departures from safety protocols regardless of who is responsible — this is the classic deference trap that patient safety training is designed to prevent.', 0),
    (v_s09, 2, 'Isaac quietly says to his supervisor, before the local anaesthetic takes full effect, ''I can''t see a pre-operative X-ray in the notes — should we take one before we proceed?''', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Isaac raises the concern at the only point it can be acted on, before the procedure becomes irreversible, in a private and respectful way that allows the supervisor to respond without embarrassment. GDC standards require all team members to speak up when clinical protocols are at risk of being missed, and this response does so at exactly the right moment.', 1),
    (v_s09, 2, 'Isaac says nothing during the procedure but raises the missing radiograph in his end-of-placement feedback form two weeks later.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because recording the concern through formal feedback channels has some educational value. However, waiting two weeks means the protocol breach on an irreversible procedure goes unaddressed and unrecorded at the time it occurred. If a complication later arose, there would be no contemporaneous record of what was observed. Speaking up before the extraction was the proportionate and timely response.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 1, 'That the charity is for a cause the F1 personally believes is genuinely worthwhile.', 'Of minor importance', 'This is of minor importance because the merits of the charity itself are largely separate from the question of whether the consultant is exerting inappropriate pressure. The F1 may, on their own initiative, choose to support a worthy cause, but the cause does not justify the consultant''s behaviour or change whether the request is appropriate. GMC Good Medical Practice requires power within professional relationships to be used responsibly — the cause does not change the dynamic.', 0),
    (v_s10, 1, 'Whether the consultant is in a position to influence the F1''s references, training opportunities, or rotation feedback.', 'Very important', 'This is very important because it transforms what could be a simple request into one with implicit coercion, which engages GMC Good Medical Practice principles around the proper use of professional authority. A senior who can shape an F1''s career is in a position where any request can feel obligatory, and the F1 must consider whether the consultant''s behaviour itself is appropriate use of their role — not just whether they personally wish to donate.', 1),
    (v_s10, 1, 'That the F1 is on a tight personal budget while paying off student loans.', 'Of minor importance', 'This is of minor importance because the F1''s personal financial circumstances are a practical factor in any voluntary donation but do not engage the central professional issue — the consultant''s repeated approaches and explicit linking of donations to recognition would still be inappropriate regardless of whether the F1 could afford to donate. GMC Good Medical Practice requires that responses to inappropriate use of professional authority are guided by the conduct itself, not by personal circumstances that might happen to make compliance easier or harder.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s01, 2, 'Tomás says nothing during the consultation but, after the patient has been discharged, reviews the notes himself and asks the consultant whether a more thorough assessment might have been warranted given the pain history.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Tomás is taking the concern seriously and following it up with the consultant, which aligns with the GMC duty to act on patient safety concerns and to communicate professionally. However, by saying nothing during the consultation itself he allows the patient to be discharged without a thorough pain assessment, missing the chance to address the immediate safety question. A better response would raise the concern at the time, before the patient leaves.', 0),
    (v_s01, 2, 'Tomás continues with his other tasks, reasoning that the consultant is far more experienced and that responsibility for the decision sits with them.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because failing to act on a clear potential patient safety concern — a senior dismissing reported pain without proper assessment — falls into the inaction trap and contradicts the GMC''s first duty: making the care of the patient your first concern. The ''consultant is more experienced'' rationale is the classic deference trap; seniority does not exempt a clinical decision from being questioned where safety may be at risk.', 1),
    (v_s01, 2, 'Tomás politely asks the consultant in private, before discharge, whether they would like him to take a more detailed pain history given the severity the patient is reporting.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Tomás raises the concern privately, respectfully, and in a way that focuses on the patient (offering to take a more detailed history) rather than challenging the consultant directly. This follows the GMC duty to act when patient safety may be compromised, while preserving professional working relationships and respecting the consultant''s overall responsibility.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s02, 2, 'Lewis takes a single tablet on the morning of his hardest exam, reasoning that one-off use is unlikely to cause any real problems.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because taking an unprescribed prescription medication risks unknown side effects and raises academic integrity questions, conflicting with the standards expected of healthcare students. However, the harm here is limited and primarily to Lewis himself: a single use, no patient involvement, no supply or distribution. It falls short of ''very inappropriate'' which would apply to repeated use, supplying others, or use during direct patient care.', 0),
    (v_s02, 2, 'Lewis declines politely and explains he doesn''t want to take an unprescribed drug, but doesn''t raise the matter with Marco any further.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Lewis is making the right personal decision and protecting his own integrity. However, he misses the chance to address the wider concern — that Marco appears to be supplying prescription medication to peers, which is itself a fitness-to-practise issue and a potential risk to others who accept. A more complete response would raise this with Marco and signpost support.', 1),
    (v_s02, 2, 'Lewis declines firmly and gently raises with Marco that obtaining and supplying prescription medication this way is unsafe and a potential fitness-to-practise concern, suggesting Marco speak to his GP if he is genuinely struggling.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Lewis declines clearly (protecting his own integrity), addresses Marco''s behaviour as a fitness-to-practise concern, and offers a constructive route to support — all consistent with the GMC''s expectation that healthcare students raise concerns about colleagues'' conduct or wellbeing while treating each other with respect.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s03, 1, 'Whether senior cover (a registrar or consultant) will be available throughout the night to support whoever covers the shift.', 'Important', 'This is important because the availability of senior support directly affects the level of risk associated with Aisha working tired — a registrar or consultant on hand can mitigate decision-making errors. It is genuinely relevant to the decision, but not the most critical factor; even with senior cover, severe fatigue can still compromise her own judgement and patient safety.', 0),
    (v_s03, 1, 'That working while severely fatigued increases the risk of clinical errors that could harm patients.', 'Very important', 'This is very important because tiredness directly increases the likelihood of clinical errors, which is a patient safety issue and the highest priority under GMC Good Medical Practice. Aisha has a duty to recognise her own limits — working when too fatigued to do so safely is itself a fitness-to-practise concern.', 1),
    (v_s03, 1, 'That the rota coordinator may be annoyed if Aisha refuses.', 'Not important at all', 'This is not important at all because the coordinator''s reaction relates to Aisha''s reputation and personal comfort, not to patient safety or her duty of care. Allowing concerns about a colleague''s annoyance to drive a decision about whether to work while severely fatigued would invert the priority hierarchy. A coordinator''s frustration is recoverable; an avoidable clinical error is not.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s04, 2, 'Devika quietly approaches the consultant after the round and respectfully mentions that she noticed the patient''s preferred name and pronouns were on the front of the notes.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Devika respects the consultant''s seniority by speaking privately, frames the issue around the patient''s documented preferences rather than as a personal criticism, and acts in line with the GMC duty to treat patients with dignity and respect. Addressing it after the round avoids embarrassing either the consultant or the patient publicly.', 0),
    (v_s04, 2, 'Devika interrupts the consultant mid-round, in front of the team and the patient, to correct the pronouns being used.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because publicly correcting a senior in front of the patient and team — even on a legitimate dignity issue — undermines team dynamics and may itself be uncomfortable for the patient by drawing further attention to their identity. The intent is right (protecting dignity) but the method risks humiliating the consultant and embarrassing the patient. The harm is real but limited and recoverable; private feedback would have achieved the same outcome more constructively.', 1),
    (v_s04, 2, 'Devika says nothing because consultants should already know how to address patients and it isn''t her place as a student to correct one.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because it falls squarely into the ''not my place'' trap. The GMC requires all team members, regardless of seniority, to respect patient dignity. Choosing silence on a repeated, observable failure of dignity — affecting the patient in front of her — fails the patient and normalises the behaviour for the rest of the team.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s05, 2, 'Owen mentions his observation casually to his fellow medical students over lunch to see whether they have noticed anything similar.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because Owen is treating a probity concern as gossip rather than acting through proper channels. Discussing the consultant with peers can damage the consultant''s reputation prematurely, fails to address the issue, and risks the concern circulating without ever being investigated. The consequences are real but limited; the right principle (concern about probity) is being expressed in the wrong forum.', 0),
    (v_s05, 2, 'Owen raises his concern with his medical school placement lead, describing the pattern factually and noting his uncertainty about the arrangement.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Owen reports the concern factually through an appropriate channel (the medical school), without making accusations and acknowledging his own uncertainty. This aligns with the GMC duty to raise concerns about a colleague''s professional conduct and the duty of probity, while leaving fact-finding to those with authority to investigate.', 1),
    (v_s05, 2, 'Owen decides to ignore it because consultants'' contracts are complicated and probity issues are not really a student matter.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because ignoring an apparent probity issue that affects NHS patients (who are being denied appointments) is the inaction trap dressed up as humility. Probity is core to GMC Good Medical Practice, and the ''students don''t get involved'' rationale wrongly suggests there are professional duties students are exempt from.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s06, 1, 'Whether Mrs Jenkins''s behaviour reflects pain, delirium, or distress that could be addressed in another way before any restraint is considered.', 'Very important', 'This is very important because identifying treatable causes of agitation (pain, infection delirium, hunger, the discomfort of the IV itself) is a core part of acting in the patient''s best interests under the Mental Capacity Act framework. Restraint must always be the least restrictive option — exploring alternatives is not optional, it is required.', 0),
    (v_s06, 1, 'That the family will be unhappy if their request is refused.', 'Of minor importance', 'This is of minor importance because, while maintaining a working relationship with the family is helpful and they are advocates for Mrs Jenkins, their unhappiness cannot determine a clinical decision about restraint. The decision must be based on Mrs Jenkins''s best interests, not on what the family demands. Their views are worth listening to but cannot be the deciding factor.', 1),
    (v_s06, 1, 'That clear documentation of any decision and the reasoning behind it will be needed in the patient''s notes.', 'Important', 'This is important because clear documentation of the decision and the reasoning behind it protects the patient, the team, and the family, and forms part of routine professional practice. It is not the most critical factor in the decision itself (best interests are), but it is a meaningful safeguard that supports good care and accountability.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s07, 2, 'Priya keeps the watch but tells no one, reasoning that the family clearly intended it as a personal thank-you.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because keeping a high-value gift undeclared is a serious breach of GMC probity guidance and most NHS trust gift policies. It risks the appearance — and potentially the reality — of preferential treatment, undermines public trust, and could amount to professional misconduct. The ''personal thank-you'' framing is the classic self-justification trap.', 0),
    (v_s07, 2, 'Priya immediately informs her clinical supervisor, declares the gift in line with trust policy, and arranges to return the watch to the family with a thank-you note explaining she cannot accept it.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Priya is acting transparently in line with both GMC probity standards and trust gift policy. Informing her supervisor, declaring the gift, and returning it with a respectful explanation preserves the family relationship, protects Priya''s professional standing, and demonstrates the openness expected of all clinicians.', 1),
    (v_s07, 2, 'Priya privately mentions the gift to her clinical supervisor but asks them not to formally declare it, hoping to avoid making the family feel offended.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Priya is taking a step in the right direction by raising the gift with her supervisor rather than concealing it entirely. However, asking her supervisor not to formally declare a gift of this value bypasses the proper trust process and puts the supervisor in an uncomfortable position. A clean, formal declaration is what the policy exists for.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s08, 1, 'Whether this appears to be a single occurrence or part of a wider pattern of falsified observations.', 'Important', 'This is important because understanding whether this is an isolated incident or part of a wider pattern affects the urgency and scale of the response, even though the underlying duty to raise the concern remains the same in either case. Knowing the context helps Marcus communicate the issue accurately to whoever investigates.', 0),
    (v_s08, 1, 'Whether unstable patients may have deteriorated without anyone noticing because real observations were not actually taken.', 'Very important', 'This is very important because the entire purpose of routine observations is to detect clinical deterioration early; falsified readings could mean an unstable patient is missed entirely. This goes directly to patient safety, which is the highest priority under GMC Good Medical Practice.', 1),
    (v_s08, 1, 'That Heather and Marcus have known each other since the start of medical school and often socialise together.', 'Not important at all', 'This is not important at all because personal friendship cannot override the professional duty to raise concerns about patient safety and integrity. The GMC is explicit that doctors and students must put patient welfare ahead of personal relationships; allowing the friendship to silence Marcus would be the self-interest trap.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s09, 2, 'The group members agree to credit Rohan as lead author so that he releases the data and the deadline can be met.', 'Inappropriate, but not awful', 'This is inappropriate, but not awful because conceding to coercion in order to meet the deadline rewards Rohan''s behaviour, may misrepresent contributions on a piece of academic work, and sets a poor precedent for future group work. The harm is meaningful but limited — the deadline is met and academic dishonesty is not necessarily involved if contributions are reflected reasonably — so it falls short of ''very inappropriate''.', 0),
    (v_s09, 2, 'The group members ask Rohan to meet privately to discuss authorship fairly, agree contributions in writing, and remind him that withholding shared research data breaches academic integrity rules.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because the group is dealing with the issue directly and constructively: meeting Rohan privately to discuss authorship fairly, putting the agreement in writing, and clearly naming the integrity issue with withholding shared data. This aligns with academic integrity expectations and the GMC values of honesty and constructive teamwork.', 1),
    (v_s09, 2, 'The group members complain about Rohan in the course''s general WhatsApp chat to put social pressure on him to release the data.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because public shaming on a course-wide chat is unprofessional, escalates the conflict in front of the wider cohort, and damages Rohan''s reputation without giving him any chance to respond privately. It is the confrontation trap — a real concern (Rohan''s behaviour) expressed through a method that itself fails the standards expected of healthcare students.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s10, 2, 'Yuki says nothing in the moment but looks up the dental defence union''s guidance on retained instruments later that evening to inform her next steps.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Yuki recognises she may need to act and is informing herself before doing so. However, by saying nothing in the moment, she allows the patient to leave the clinic without being told about a retained instrument — which the duty of candour requires. A better response would raise the issue immediately, with the supervisor and the patient still present.', 0),
    (v_s10, 2, 'Yuki agrees with the supervisor and trusts that as the qualified dentist he knows whether the fragment is significant enough to mention to the patient.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the duty of candour requires patients to be informed when something has gone wrong in their care, regardless of how minor the clinician judges it. Deferring to the supervisor''s view that the patient does not need to know participates in the concealment and treats hierarchy as more important than honesty with the patient.', 1),
    (v_s10, 2, 'Yuki gently tells the supervisor in private, before the patient leaves, that she thinks the patient should be informed about the retained fragment, and adds that if he disagrees she will need to raise it with the clinic lead.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Yuki upholds the duty of candour by ensuring the patient is informed before leaving, raises the issue privately and respectfully with the supervisor first, and is clear about her own willingness to escalate if needed. This matches GMC Good Medical Practice on openness when things go wrong, while also respecting the supervisor''s role.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s11, 1, 'That Hassan still needs gynaecology cases logged for his portfolio this year.', 'Not important at all', 'This is not important at all because Hassan''s educational needs cannot override a patient''s clearly expressed preference about who is involved in her examination. The GMC requires that patient autonomy and dignity take priority — using a teaching opportunity as a reason to override consent would invert the priority hierarchy.', 0),
    (v_s11, 1, 'That the patient''s right to choose who is present during her examination is fundamental to her autonomy and dignity.', 'Very important', 'This is very important because consent — including consent to who is present during an intimate examination — is fundamental to GMC Good Medical Practice. A patient''s right to choose who is involved is non-negotiable, and respecting it is part of treating patients with dignity.', 1),
    (v_s11, 1, 'Whether the patient has given any reason for her preference, such as a previous traumatic experience.', 'Of minor importance', 'This is of minor importance because, while understanding the reason might help the team respond compassionately, the patient does not need to justify her preference for it to be respected. Hassan''s appropriate action — to step out gracefully — is the same regardless of the reason.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s12, 1, 'That the conversation is happening at a social event well outside of university hours.', 'Of minor importance', 'This is of minor importance because where Alex disclosed the behaviour does not change its fitness-to-practise implications. Conduct outside university hours can still amount to professional misconduct — the casual social context may slightly affect how Nina chooses to raise it, but it does not affect whether she should.', 0),
    (v_s12, 1, 'That regular use of an illegal Class A drug is a fitness-to-practise issue and could put future patients at risk.', 'Very important', 'This is very important because regular use of an illegal Class A drug is a serious fitness-to-practise issue — it engages legal, health, and patient safety concerns and is the kind of conduct the GMC explicitly flags as incompatible with practice. Nina''s professional duty to raise concerns about a colleague''s fitness applies regardless of the social context in which she found out.', 1),
    (v_s12, 1, 'That Alex would be embarrassed if Nina raised the issue with him directly.', 'Not important at all', 'This is not important at all because concern for Alex''s awkwardness or embarrassment cannot override Nina''s professional duty to address a fitness-to-practise issue. Wanting to avoid uncomfortable conversations is the self-interest trap; it must not drive professional decisions.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s13, 2, 'Theo continues with the injection quickly so that it is over with, reasoning that prolonging things will only make the patient more anxious.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because Theo is proceeding with a procedure on a patient showing signs of acute distress, without checking what is happening or seeking ongoing consent. This breaches GMC duties on consent, dignity, and patient safety, and could cause real harm — both physically (movement during the injection) and psychologically (entrenching a phobia).', 0),
    (v_s13, 2, 'Theo stops, lowers the chair slightly, calmly tells the patient he is pausing, and asks his supervising dentist to come over before deciding how to proceed.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Theo recognises a patient in distress, halts the procedure, takes a calming and supportive action, and escalates appropriately to his supervising dentist. This is exactly the role-appropriate response for a dental student: stop, support, and seek senior input rather than pushing on alone.', 1),
    (v_s13, 2, 'Theo stops the procedure, reassures the patient, and once she says she feels ready continues with the injection on his own without involving his supervisor.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Theo correctly recognises the patient''s distress and stops the procedure, which protects her in the moment. However, by not consulting his supervising dentist about a possibly phobic reaction before continuing, he is acting beyond his stage of training and missing the chance to plan a safer continuation (for example, with adjuncts or by rebooking with an explicit phobia plan).', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s14, 2, 'Bethany leaves the group quietly and decides to forget about it since she didn''t write any of the messages herself.', 'A very inappropriate thing to do', 'This is a very inappropriate thing to do because the group represents a serious confidentiality breach — patients are identifiable and being mocked by clinical staff. Leaving without acting fails the GMC duty to raise concerns about colleagues'' professional conduct and to protect patient confidentiality, and the ''I didn''t write it'' reasoning is a clear example of the inaction trap.', 0),
    (v_s14, 2, 'Bethany takes screenshots and reports the group through her medical school''s professionalism reporting route, after first raising her concerns directly with whoever added her.', 'A very appropriate thing to do', 'This is a very appropriate thing to do because Bethany preserves evidence of an ongoing confidentiality breach, uses the medical school''s formal professionalism route, and gives the system the information it needs to investigate. This matches GMC duties on raising concerns and protecting patient confidentiality, while still treating the person who added her with appropriate openness.', 1),
    (v_s14, 2, 'Bethany privately messages the person who added her, asking them to stop the patient-related posts and to review who is in the group.', 'Appropriate, but not ideal', 'This is appropriate, but not ideal because Bethany is taking direct action with the person involved, which is generally a constructive first step. However, the breach in this scenario is serious — patients are identifiable and being mocked, the messages are recent, and the group includes multiple staff. A confidentiality breach of this scale also needs formal escalation; relying on a single private message is unlikely to be adequate.', 2);
  INSERT INTO situational_judgement_scenarios (body)
  INSERT INTO situational_judgement_questions (scenario_id, label_set, question_text, correct_answer, answer_reason, order_index) VALUES
    (v_s15, 1, 'That the F1 will be embarrassed if it turns out to be his mistake.', 'Not important at all', 'This is not important at all because the F1''s reputation cannot be weighed against the very real risk of a wrong-patient error. Allowing concern for a colleague''s embarrassment to influence whether to flag a labelling discrepancy is the self-interest trap and would breach the GMC priority of patient safety.', 0),
    (v_s15, 1, 'That sending a mislabelled sample could result in another patient being treated based on results that don''t belong to them.', 'Very important', 'This is very important because mislabelled samples are a recognised cause of serious clinical harm — the wrong patient can receive a treatment based on results that don''t belong to them. Patient safety is the highest priority under GMC Good Medical Practice, which requires Ines to act now rather than send the sample as it is.', 1),
    (v_s15, 1, 'Whether the lab is about to close for the night and the sample is genuinely time-critical.', 'Important', 'This is important because the urgency of the test and the lab''s hours genuinely affect how — though not whether — Ines acts. If the sample is genuinely urgent, she still cannot send it as it is, but she may need to escalate quickly to the F1 to redraw and relabel rather than simply binning the sample. The clinical context matters; it does not override the safety issue.', 2);
